// Question banks: quantum, bonding, stoich, thermo1, thermo2, equilibrium.
// Convention: first 5 are warm-ups, the next 20 are CCC/CCO/USNCO style.
import type { QuizQ } from './framework';

export const QUANTUM_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'qua-001', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Maximum number of electrons in a p subshell?', opts: ['6', '4', '2', '10'], a: 0, why: 'Three p orbitals × 2 electrons each = 6.' },
  { id: 'qua-002', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which orbital is spherical?', opts: ['p', 's', 'd', 'f'], a: 1, why: 's orbitals are spheres; p are dumbbells, d mostly cloverleafs.' },
  { id: 'qua-003', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many orbitals are in the n = 2 shell?', opts: ['1', '2', '4', '8'], a: 2, why: 'One 2s + three 2p = 4 orbitals (n² rule: 2² = 4), holding up to 8 electrons.' },
  { id: 'qua-004', topic: 'quantum', skill: 'atomic/configuration', q: 'Ground-state electron configuration of Na (Z = 11)?', opts: ['[Ar]4s¹', '[Ne]3p¹', '[He]2s²2p⁶3s²', '[Ne]3s¹'], a: 3, why: '10 electrons fill 1s²2s²2p⁶ = [Ne]; the 11th goes into 3s.' },
  { id: 'qua-005', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which quantum number determines the SHAPE of an orbital?', opts: ['ℓ', 'n', 'mℓ', 'ms'], a: 0, why: 'ℓ sets the shape family (0 = s, 1 = p, 2 = d…); n sets size/energy, mℓ orientation, ms spin.' },
  // ---- olympiad ----
  { id: 'qua-006', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'How many radial nodes does a 4d orbital have?', opts: ['0', '1', '2', '3'], a: 1, why: 'Radial nodes = n − ℓ − 1 = 4 − 2 − 1 = <b>1</b>. (Angular nodes = ℓ = 2, total = n − 1 = 3.)', misconception: 'There are three different node counts and they are easy to swap. Total nodes = n − 1, angular (planar) nodes = ℓ, and radial (spherical) nodes = n − ℓ − 1. A 4d orbital has 3 total, 2 angular and only 1 radial. Answering "2" or "3" here almost always means quoting one of the other two counts, so write all three down before choosing.' },
  { id: 'qua-007', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Which quantum number set is IMPOSSIBLE?', opts: ['n=3, ℓ=2, mℓ=−2', 'n=4, ℓ=0, mℓ=0', 'n=2, ℓ=2, mℓ=0', 'n=5, ℓ=3, mℓ=3'], a: 2, why: 'ℓ can only go up to n−1, so n=2 allows ℓ = 0 or 1 only. "2d" orbitals don\'t exist.' },
  { id: 'qua-008', tier: 3, topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Why is the first ionization energy of O slightly LOWER than N?', opts: ['O is larger than N', 'O has more shielding electrons', 'N has a full 2p subshell', 'pairing repulsion in O\'s 2p⁴'], a: 3, why: 'N is 2p³ (half-filled, all unpaired). O\'s fourth 2p electron must pair up — that repulsion makes it easier to remove.', misconception: 'Ionisation energy does not rise monotonically across a period — it steps back twice, and both dips are about electron configuration rather than size. B (2s²2p¹) is easier to ionise than Be because the 2p electron is higher in energy than the filled 2s; O (2p⁴) is easier than N because its fourth 2p electron must pair in an already-occupied orbital and pays the repulsion. Reaching for "O is bigger" is the trend answer, and it is the wrong mechanism.' },
  { id: 'qua-009', topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Largest radius in the isoelectronic series O²⁻, F⁻, Na⁺, Mg²⁺?', opts: ['O²⁻', 'F⁻', 'Na⁺', 'Mg²⁺'], a: 0, why: 'All have 10 electrons; O²⁻ has the fewest protons (8) pulling them in, so it\'s the largest.' },
  { id: 'qua-010', tier: 3, topic: 'quantum', skill: 'atomic/spectra', q: 'The n=3 → n=2 transition in hydrogen emits light at about…', opts: ['122 nm (UV)', '486 nm (blue-green)', '656 nm (red)', '1875 nm (IR)'], a: 2, why: 'Balmer series, first line: ΔE = 13.6(1/4 − 1/9) = 1.89 eV → λ = 1240/1.89 ≈ <b>656 nm</b>, the H-α red line.', misconception: 'The series is named for the LOWER level, not the upper one: transitions ending at n = 1 are Lyman (UV, 122 nm), at n = 2 Balmer (visible), at n = 3 Paschen (IR, 1875 nm). Within Balmer, 3 → 2 is the smallest energy gap and therefore the LONGEST wavelength, 656 nm red; 486 nm blue-green is 4 → 2. Picking 486 usually means counting the visible lines from the blue end, or assuming the first line of a series is the most energetic one.' },
  { id: 'qua-011', topic: 'quantum', skill: 'atomic/pes', q: 'In the PES spectrum of neon, the peak at HIGHEST binding energy corresponds to…', opts: ['2p electrons', '1s electrons', '2s electrons', 'valence electrons'], a: 1, why: 'Core 1s electrons sit closest to the nucleus and need the most energy to remove — they appear at the highest ionization energy.' },
  { id: 'qua-012', topic: 'quantum', skill: 'atomic/configuration', q: 'Number of unpaired electrons in ground-state Cr (Z = 24)?', opts: ['6', '5', '4', '2'], a: 0, why: 'Cr is the exception: [Ar]4s¹3d⁵ — one unpaired 4s plus five unpaired 3d = <b>6</b>.', misconception: 'Cr and Cu are not exceptions you can derive from the aufbau order — they are exceptions <em>to</em> it, and they must be known. Cr is [Ar]4s¹3d⁵ and Cu is [Ar]4s¹3d¹⁰, because a half-filled or filled d set plus a half-filled 4s beats the naive 4s²3d⁴ / 4s²3d⁹. Filling by the diagonal rule without checking for these two is what produces the "4 unpaired" answer.' },
  { id: 'qua-013', topic: 'quantum', skill: 'atomic/configuration', q: 'Electron configuration of Fe²⁺?', opts: ['[Ar]4s²3d⁴', '[Ar]3d⁵', '[Ar]4s¹3d⁵', '[Ar]3d⁶'], a: 3, why: 'Cations lose 4s electrons FIRST: Fe [Ar]4s²3d⁶ → Fe²⁺ [Ar]3d⁶. (Fe³⁺ is the extra-stable d⁵.)', misconception: 'Transition-metal cations lose their <em>4s</em> electrons first, not the 3d electrons the aufbau order filled last. Once 3d is occupied it drops below 4s in energy, so Fe [Ar]4s²3d⁶ ionises to Fe²⁺ [Ar]3d⁶ — never [Ar]4s²3d⁴. "Last in, first out" is the wrong rule here, and it costs marks on every d-block configuration question.' , why2: 'Build the ion directly instead of building the atom and then subtracting. For any d-block cation, the 4s orbital is simply not occupied: once 3d is populated the extra nuclear pull drops it below 4s, so the ion\'s electrons fill [Ar] and then 3d, full stop. Iron is group 8, so it brings 8 electrons past argon; take two away for the 2+ charge and 6 remain — <b>[Ar]3d⁶</b>, no 4s bookkeeping needed. The same one-step rule gives Sc³⁺ [Ar], Ti²⁺ [Ar]3d², Cu²⁺ [Ar]3d⁹. The aufbau diagonal is a recipe for filling <em>neutral</em> atoms, not a fixed energy ladder you can run backwards.' },
  { id: 'qua-014', topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Which element shows the biggest jump between its 1st and 2nd ionization energies?', opts: ['Mg', 'Al', 'Na', 'Si'], a: 2, why: 'After losing one electron Na⁺ has a noble-gas core — ripping the second electron out of that core costs ~10× more. The jump position identifies the group.' },
  { id: 'qua-015', topic: 'quantum', skill: 'atomic/quantum-foundations', q: 'An electron and a proton move at the same speed. The electron\'s de Broglie wavelength is…', opts: ['shorter', 'about 1800× longer', 'the same', 'zero'], a: 1, why: 'λ = h/mv — the electron\'s mass is ~1836× smaller, so its wavelength is ~1836× longer at equal speed.', misconception: 'λ = h/mv puts mass in the <em>denominator</em>: at the same speed, the lighter particle has the LONGER wavelength. The intuition that a fast, light electron must be "smaller" in every sense is what produces the "shorter" answer. This is exactly why electron microscopes resolve better than light microscopes — accelerate the electron and you shorten λ, but comparing it with a proton at equal speed, the electron wins by its ~1836× smaller mass.' },
  { id: 'qua-016', topic: 'quantum', skill: 'atomic/quantum-foundations', q: 'In the photoelectric effect, increasing light INTENSITY (same frequency)…', opts: ['ejects more electrons, same KE', 'increases electron KE', 'stops emission', 'increases the work function'], a: 0, why: 'Each photon\'s energy (hν) is unchanged — more photons just eject more electrons. Only frequency raises KE = hν − φ. This killed the wave model.', misconception: 'Intensity and frequency do completely different things in the photoelectric effect, and conflating them is what the experiment was built to expose. One photon ejects one electron, so brighter light (more photons per second) ejects more electrons — each still with KE = hν − φ. Only raising the <em>frequency</em> raises the kinetic energy, and below the threshold frequency no intensity at all will eject anything. Classical wave theory predicted the opposite on both counts.' },
  { id: 'qua-017', topic: 'quantum', skill: 'atomic/spectra', q: 'Which hydrogen transition emits the HIGHEST-energy photon?', opts: ['n=4 → n=2', 'n=3 → n=2', 'n=5 → n=3', 'n=2 → n=1'], a: 3, why: 'The 1/n² spacing is hugely lopsided: dropping to n=1 (Lyman) releases more than any transition between higher levels. ΔE = 13.6(1 − ¼) = 10.2 eV.' },
  { id: 'qua-018', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'In the HYDROGEN atom (one electron), which orbitals have the same energy?', opts: ['only orbitals with the same ℓ', '3s < 3p < 3d always', '3s, 3p, and 3d all equal', 'none are degenerate'], a: 2, why: 'With one electron there\'s no shielding — energy depends on n only, so all nine n=3 orbitals are degenerate. Multi-electron atoms split them (s < p < d).', misconception: 'The familiar ns &lt; np &lt; nd ordering is a <em>multi-electron</em> phenomenon, caused by electrons shielding one another unequally. Hydrogen has one electron and nothing to shield it, so its energy depends on n alone and all nine n = 3 orbitals are exactly degenerate. Carrying the "s is always lower" rule into the one-electron atom is the trap.' },
  { id: 'qua-019', tier: 3, topic: 'quantum', skill: 'atomic/pes', q: 'A PES spectrum shows two peaks with area ratio 2:1. The element is…', opts: ['He', 'Li', 'Be', 'B'], a: 1, why: 'Li: 1s²2s¹ → two electrons in one peak, one in another = 2:1. (Be would be 2:2 = 1:1; B gives three peaks.)', misconception: 'Peak COUNT tells you how many occupied subshells there are; peak AREA tells you how many electrons sit in each. Two peaks alone would fit Li or Be equally — only the 2:1 area separates them, since Be (1s²2s²) gives 2:2 and B adds a third peak for its 2p electron. Choosing Be means reading the number of peaks and ignoring their sizes.' },
  { id: 'qua-020', topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Which element has the most NEGATIVE (most favorable) electron affinity?', opts: ['F', 'Cl', 'O', 'N'], a: 1, why: 'Cl, not F! F\'s compact 2p shell suffers strong electron–electron repulsion when gaining an electron. A classic counter-trend fact.', misconception: 'Electron affinity is not simply "the trend continued to fluorine". Cl (−349 kJ/mol) is more exothermic than F (−328): F\'s 2p shell is so compact that an incoming electron pays a large electron–electron repulsion penalty on arrival. The same effect makes O less favourable than S. Nearly every second-period element sits slightly off the trend for this reason.' },
  { id: 'qua-021', topic: 'quantum', skill: 'atomic/periodic-trends', q: 'Zeff on the valence electron increases across a period mainly because…', opts: ['n increases', 'shielding increases faster than Z', 'protons are added while shielding stays roughly constant', 'orbitals shrink spontaneously'], a: 2, why: 'Same-shell electrons shield each other poorly (~0.35 each), so each added proton raises the net pull on valence electrons.' },
  { id: 'qua-022', topic: 'quantum', skill: 'atomic/quantum-numbers', q: 'Total nodes and radial nodes of a 5f orbital?', opts: ['3 total, 0 radial', '5 total, 2 radial', '4 total, 3 radial', '4 total, 1 radial'], a: 3, why: 'Total = n − 1 = 4; angular = ℓ = 3; radial = n − ℓ − 1 = 1.' },
  { id: 'qua-023', topic: 'quantum', skill: 'atomic/spectra', q: 'Energy needed to ionize a hydrogen atom already excited to n = 2?', opts: ['3.4 eV', '6.8 eV', '13.6 eV', '10.2 eV'], a: 0, why: 'E₂ = −13.6/2² = −3.4 eV, so lifting it to E = 0 takes <b>3.4 eV</b>. One-quarter of the ground-state value.' },
  { id: 'qua-024', topic: 'quantum', skill: 'atomic/configuration', q: 'Which species is NOT isoelectronic with the others?', opts: ['Ar', 'Na⁺', 'Cl⁻', 'K⁺'], a: 1, why: 'Ar, K⁺, Cl⁻ all have 18 electrons; Na⁺ has 10 (isoelectronic with Ne instead).' },
  { id: 'qua-025', topic: 'quantum', skill: 'atomic/quantum-foundations', q: 'The Heisenberg uncertainty principle says that…', opts: ['electrons repel each other', 'energy isn\'t conserved briefly', 'position and momentum can\'t both be known exactly', 'orbitals are exact paths'], a: 2, why: 'Δx·Δp ≥ ħ/2 — this is WHY we speak of orbitals (probability clouds) rather than orbits (paths).' },
];

export const BONDING_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'bon-001', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'How many covalent bonds does carbon usually form?', opts: ['2', '3', '4', '6'], a: 2, why: 'Carbon has 4 valence electrons and 4 empty slots — tetravalence is the backbone of organic chemistry.' },
  { id: 'bon-002', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'The shape of CO₂ is…', opts: ['bent', 'tetrahedral', 'trigonal planar', 'linear'], a: 3, why: 'Two double-bond domains, no lone pairs on C → 180° linear. (Contrast SO₂, which has a lone pair and is bent.)' },
  { id: 'bon-003', topic: 'bonding', skill: 'bonding/bond-properties', q: 'A double bond consists of…', opts: ['1 σ + 1 π', '2 π bonds', '2 σ bonds', '1 σ + 2 π'], a: 0, why: 'The first bond of any multiple bond is σ (head-on); extras are π (sideways p overlap). Triple = 1σ + 2π.' },
  { id: 'bon-004', topic: 'bonding', skill: 'bonding/polarity', q: 'A bond between atoms with an electronegativity difference of about 0.5 is best called…', opts: ['nonpolar covalent', 'polar covalent', 'ionic', 'metallic'], a: 1, why: 'ΔEN ≈ 0.4–1.8 is polar covalent (unequal sharing). Below ~0.4 is nonpolar; above ~1.8 the bond is essentially ionic (electron transfer).' },
  { id: 'bon-005', topic: 'bonding', skill: 'bonding/polarity', q: 'The bond in NaCl is best described as…', opts: ['nonpolar covalent', 'polar covalent', 'ionic, from the large ΔEN', 'metallic'], a: 2, why: 'ΔEN ≈ 2.1 — the metal transfers its electron to the nonmetal, giving an ion lattice.' },
  // ---- olympiad ----
  { id: 'bon-006', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'What is the molecular shape of XeF₄?', opts: ['tetrahedral', 'seesaw', 'square pyramidal', 'square planar'], a: 3, why: '6 domains: 4 bonds + 2 lone pairs trans to each other → AX₄E₂ = <b>square planar</b>.', misconception: 'The <em>shape</em> of a molecule names where the atoms are; the <em>electron geometry</em> names where all the domains are, lone pairs included. XeF₄ has six domains, so its electron geometry is octahedral — but with the two lone pairs opposite each other, the four atoms describe a square plane. Answering "tetrahedral" or "square pyramidal" means either forgetting the lone pairs exist or forgetting that they are invisible in the shape.' },
  { id: 'bon-007', topic: 'bonding', skill: 'bonding/mo-theory', q: 'Which molecule is paramagnetic?', opts: ['O₂', 'N₂', 'F₂', 'C₂'], a: 0, why: 'O₂ has 2 unpaired electrons in its degenerate π* orbitals — liquid O₂ sticks to a magnet. MO theory\'s signature win.' },
  { id: 'bon-008', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Bond order of the superoxide ion O₂⁻?', opts: ['1', '1.5', '2', '2.5'], a: 1, why: '13 valence e⁻ → extra electron in π* → BO = (8−5)/2 = 1.5. Order: O₂⁺ 2.5 > O₂ 2 > O₂⁻ 1.5 > O₂²⁻ 1.', misconception: 'Superoxide (O₂⁻) and peroxide (O₂²⁻) are different ions and only one extra electron separates them. One electron into π* costs half a bond (BO 1.5); two extra electrons cost a full bond (BO 1), which is the peroxide value. Answering 1 means counting the charge as though it were 2− — always read the charge before you fill the antibonding set.' },
  { id: 'bon-009', topic: 'bonding', skill: 'bonding/hybridisation', q: 'Hybridization of sulfur in SF₄?', opts: ['sp²', 'sp³', 'sp³d', 'sp³d²'], a: 2, why: '4 bonds + 1 lone pair = 5 domains → sp³d, seesaw shape.', misconception: 'Hybridisation counts electron <em>domains</em>, not bonds. SF₄ has four bonds plus one lone pair — five domains — so it is sp³d and seesaw, not the sp³ that counting bonds alone would suggest. Any lone pair on the central atom occupies a hybrid orbital and must be counted before the label is assigned.' },
  { id: 'bon-010', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Which has the LARGEST bond angle?', opts: ['BF₃', 'NH₃', 'CH₄', 'H₂O'], a: 0, why: 'BF₃ is trigonal planar (120°) > CH₄ 109.5° > NH₃ 107° > H₂O 104.5° — lone pairs compress angles.' },
  { id: 'bon-011', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Formal charge on N in the nitrate ion NO₃⁻?', opts: ['−1', '0', '+2', '+1'], a: 3, why: 'FC = 5 − 0 − ½(8) = <b>+1</b>. The −1 charges sit on the singly-bonded oxygens (−2 total O, +1 N = −1 overall).', misconception: 'Formal charge, oxidation state and ionic charge are three different bookkeeping systems and they rarely agree. Formal charge splits every bonding pair evenly (FC = valence − lone − ½bonding), giving N in NO₃⁻ a value of +1 even though the ion as a whole is −1 and nitrogen\'s oxidation state is +5. Picking "−1" is reading the ion\'s charge off the label instead of computing the atom\'s.' },
  { id: 'bon-012', topic: 'bonding', skill: 'bonding/bond-properties', q: 'The N–O bond order in NO₃⁻ is…', opts: ['1', '1.5', '1.33', '2'], a: 2, why: 'One double bond delocalized over three equivalent positions: 4 bonds / 3 positions = 4/3.' },
  { id: 'bon-013', topic: 'bonding', skill: 'bonding/polarity', q: 'Which molecule has polar bonds but NO net dipole?', opts: ['CHCl₃', 'CCl₄', 'NH₃', 'SO₂'], a: 1, why: 'Four identical C–Cl dipoles in perfect tetrahedral symmetry cancel vectorially. Same logic clears CO₂, BF₃, XeF₄.', misconception: 'Molecular polarity is a <em>vector sum</em> of bond dipoles, not a yes/no check for "does it have polar bonds." CCl₄, CO₂, BF₃ and XeF₄ all contain genuinely polar bonds yet are nonpolar overall, because their symmetry makes the individual bond dipoles cancel exactly. The right question is never "are the bonds polar?" — it is "does the geometry let those dipoles cancel?"' },
  { id: 'bon-014', topic: 'bonding', skill: 'bonding/bond-properties', q: 'Shortest carbon–oxygen bond?', opts: ['C≡O in carbon monoxide', 'C=O in acetone', 'C–O in methanol', 'C–O in CO₃²⁻'], a: 0, why: 'CO has bond order 3 (isoelectronic with N₂) — higher order = shorter, stronger.' },
  { id: 'bon-015', topic: 'bonding', skill: 'bonding/hybridisation', q: 'Hybridization of the central iodine in I₃⁻?', opts: ['sp', 'sp³', 'sp³d²', 'sp³d'], a: 3, why: '2 bonds + 3 lone pairs = 5 domains (sp³d); lone pairs take the equator → linear ion.' },
  { id: 'bon-016', topic: 'bonding', skill: 'bonding/polarity', q: 'Which isomer of 1,2-dichloroethene has a dipole moment?', opts: ['both', 'trans only', 'cis only', 'neither'], a: 2, why: 'In trans, the two C–Cl dipoles point opposite ways and cancel (C₂ₕ has an inversion center). Cis adds them → polar.' },
  { id: 'bon-017', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Removing one electron from N₂ makes the bond…', opts: ['stronger', 'weaker', 'unchanged', 'ionic'], a: 1, why: 'The electron leaves a BONDING orbital: BO drops 3 → 2.5. (For O₂ the electron leaves π* antibonding, so O₂⁺ is STRONGER — compare the two cases!)', misconception: 'Whether ionisation strengthens or weakens a bond depends entirely on which orbital the electron leaves. Pull an electron out of a <em>bonding</em> orbital, as in N₂ → N₂⁺, and the bond order drops from 3 to 2.5 and the bond weakens. Pull one out of an <em>antibonding</em> orbital, as in O₂ → O₂⁺, and the bond order rises from 2 to 2.5 and the bond gets stronger. "Removing electrons always weakens bonds" is the model to discard.' , why2: 'Ask one question instead of two: <b>is the HOMO bonding or antibonding?</b> Ionisation always removes the highest-energy occupied electron, so the answer is entirely determined by what that orbital is. N₂ fills up to σ2p — bonding — so removing it costs half a bond. O₂ has two more electrons, which sit in π* — antibonding — so removing one <em>repairs</em> half a bond. The bond lengths confirm both: N₂ 110 pm lengthens to 112 pm in N₂⁺, while O₂ 121 pm contracts to 112 pm in O₂⁺. Same operation, opposite result, because the ledger entry being deleted has a different sign.' },
  { id: 'bon-018', topic: 'bonding', skill: 'bonding/mo-theory', q: 'The acetylide ion C₂²⁻ has bond order…', opts: ['3', '2', '2.5', '1'], a: 0, why: '10 valence electrons — isoelectronic with N₂ → triple bond. That\'s the C≡C in calcium carbide.' },
  { id: 'bon-019', topic: 'bonding', skill: 'bonding/mo-theory', q: 'MO theory predicts which species does NOT exist?', opts: ['H₂⁺', 'He₂²⁺', 'B₂', 'He₂'], a: 3, why: 'He₂: 2 bonding + 2 antibonding electrons → bond order 0. (H₂⁺ and He₂²⁺ both have BO ½ — weakly bound but real.)' },
  { id: 'bon-020', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Shape of ClF₃?', opts: ['trigonal planar', 'trigonal pyramidal', 'bent', 'T-shaped'], a: 3, why: '5 domains, 2 lone pairs in equatorial spots → the three bonds form a T. AX₃E₂.' },
  { id: 'bon-021', topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Which cannot have an expanded octet?', opts: ['N', 'S', 'P', 'Xe'], a: 0, why: 'Period 2 has no d orbitals available — N maxes at 4 bonds (NH₄⁺). PCl₅, SF₆, XeF₄ are all fine.', misconception: 'The "expanded octet" is only available to period 3 and beyond. Nitrogen, oxygen, carbon and fluorine have no accessible d orbitals and cannot exceed eight electrons under any circumstances — so a Lewis structure with five bonds to N is wrong, however tidy it looks. Phosphorus, sulfur and xenon can (PCl₅, SF₆, XeF₄), which is why P and N behave so differently despite sharing a group.' },
  { id: 'bon-022', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'B₂ is paramagnetic. This is evidence that…', opts: ['σ2p lies below π2p', 'π2p lies below σ2p', 'B₂ has a triple bond', 's–p mixing is absent'], a: 1, why: 'With π2p lower, B₂\'s two 2p electrons go one each into the two degenerate π orbitals (Hund) → 2 unpaired. If σ2p were lower they\'d pair up — diamagnetic. Experiment decides!', misconception: 'The "σ2p below π2p" MO ordering is <em>not</em> universal — treat it as the exception, not the rule. It applies to B₂, C₂ and N₂ specifically, because their 2s and 2p orbitals sit close enough in energy for s–p mixing to push σ2p above the π2p pair. From O₂ onward the 2s–2p gap is wider, mixing is weak, and the order flips back to the naively-expected σ2p below π2p. Always check which side of that N₂/O₂ line a diatomic is on before drawing its MO diagram from memory.' },
  { id: 'bon-023', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Bond angle comparison: NO₂⁺ vs NO₂⁻?', opts: ['NO₂⁺ smaller', 'equal', 'NO₂⁺ is linear (180°), NO₂⁻ is bent (~115°)', 'both linear'], a: 2, why: 'NO₂⁺ has 2 domains, no lone pair → linear. NO₂⁻ has a full lone pair squeezing the bond angle below 120°.', misconception: 'Charge changes the DOMAIN COUNT, so neither ion can be read off the neutral NO₂ skeleton. NO₂⁺ has two domains and no lone pair (linear, 180°), while NO₂⁻ carries a full lone pair that squeezes its angle below 120°. Expecting the cation to have the smaller angle treats positive charge as a general contraction of the geometry rather than as the removal of a lone pair.' },
  { id: 'bon-024', topic: 'bonding', skill: 'bonding/hybridisation', q: 'Which C–H bond is most acidic?', opts: ['sp³ (ethane)', 'sp² (ethylene)', 'all equal', 'sp (acetylene)'], a: 3, why: 'More s-character holds the anion\'s lone pair closer to the nucleus: sp (50% s, pKa 25) ≫ sp² (44) ≫ sp³ (50).', misconception: 'C–H acidity is not about how strongly carbon holds hydrogen; it is about how well the resulting <em>carbanion</em> is stabilised. More s-character in the hybrid holds the lone pair closer to the nucleus, so acidity runs sp (pKa ≈ 25) ≫ sp² (≈ 44) ≫ sp³ (≈ 50) — a 25-order-of-magnitude spread across identical-looking C–H bonds. Judging acidity by looking at the acid rather than its conjugate base is the general form of this mistake.' },
  { id: 'bon-025', topic: 'bonding', skill: 'bonding/bond-properties', q: 'The C–C bond length order is…', opts: ['C≡C < C=C < C–C', 'C–C < C=C < C≡C', 'C=C < C–C < C≡C', 'all equal'], a: 0, why: 'More shared pairs pull nuclei closer: 120 pm (≡) < 134 (=) < 154 (–). Strength runs the opposite way.', misconception: 'Bond length and bond strength run in <em>opposite</em> directions, and reading one off the other as if they tracked together is the trap. More shared pairs pull the nuclei closer: C≡C (120 pm) &lt; C=C (134) &lt; C–C (154), while the strengths run the other way, 837 &gt; 614 &gt; 348 kJ/mol. Shorter always means stronger for the same pair of atoms.' },
  // ---- flagship: bonding arguments, not bonding facts ----
  { id: 'bon-026', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Gas-phase C₂ is diamagnetic with a bond order of 2, yet its double bond is not the familiar σ + π pair. What is it, and why?', opts: ['Two π bonds and no net σ bond, because s–p mixing lifts σ2p above the degenerate π2p pair', 'One σ and one π bond, exactly as in ethene, because every double bond is one σ plus one π', 'One σ and two π bonds with one π orbital left empty, because carbon prefers a triple-bond framework', 'Two σ bonds built from sp hybrids, because head-on overlap is always the lower-energy option'], a: 0, why: 'Fill the diagram before naming the bond. C₂ has 8 valence electrons: σ2s² σ*2s² leaves a net of zero, and the remaining four go into the π2p pair — which in B₂, C₂ and N₂ lies <b>below</b> σ2p because s–p mixing pushes σ2p up. Bond order = (6 − 2)/2 = 2, and both bonding pairs are π. The diamagnetism is the check: a half-filled π set (as in B₂) would leave two unpaired electrons by Hund\'s rule, so a diamagnetic C₂ means the π level is full and σ2p is empty. The short 124 pm bond is a double bond made of two sideways overlaps.', misconception: 'σ-then-π is a valence-bond <em>template</em>, not a law of counting. It holds for ethene because the σ framework is filled first there, but a molecular orbital diagram allocates electrons by orbital energy, and in the first half of period 2 the π2p orbitals are the lower ones. Deciding what a bond is made of before filling the diagram is what turns C₂ into a phantom ethene; the honest order is fill, count, then describe.' },
  { id: 'bon-027', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'Dinitrogen monoxide is linear with the connectivity N–N–O (N–N 113 pm, N–O 119 pm). Which resonance structure is the leading contributor?', opts: ['N≡N⁺–O⁻, a triple N–N and a single N–O, with the negative formal charge on oxygen', 'N⁻=N⁺=O, two double bonds, with the negative formal charge on the terminal nitrogen', 'The structure carrying no formal charge at all, reached by giving the central nitrogen five bonds', 'N⁻–N⁺≡O, a single N–N and a triple N–O, placing a 2− formal charge on the terminal nitrogen'], a: 0, why: 'Two rules, applied in order. First, legality: nitrogen is a period-2 atom with no accessible d orbitals, so the zero-formal-charge structure would need ten electrons on the central N and simply does not exist — "minimise formal charge" has nothing to select here. Second, among the legal structures, prefer the one that puts negative formal charge on the more electronegative atom. Both N≡N⁺–O⁻ (0, +1, −1) and N⁻=N⁺=O (−1, +1, 0) are reasonable; the first wins because the −1 sits on oxygen, and the 2− structure loses on charge separation. The measured N–N of 113 pm, close to N₂\'s own 110 pm, is the evidence: real N₂O has substantial triple-bond character in the N–N linkage.', misconception: '"The best Lewis structure has zero formal charges" is a shortcut, not the rule, and it is only usable when a legal zero-charge structure exists. The actual rule is: satisfy the octet for period-2 atoms first, then minimise the <em>magnitude</em> of formal charges, then place any remaining negative charge on the most electronegative atom. Applying the shortcut first is what produces five-bonded nitrogen — a structure no amount of tidy arithmetic can make real.' },
  { id: 'bon-028', tier: 3, topic: 'bonding', skill: 'bonding/polarity', q: 'NH₃ has a dipole moment of 1.47 D, but NF₃ — built from far more polar bonds — measures only 0.24 D. Both are trigonal pyramidal. The reason is…', opts: ['The N–F bond dipoles point away from nitrogen and oppose the lone-pair moment, whereas in NH₃ the bond and lone-pair moments point the same way', 'NF₃ is much closer to planar than NH₃, so its three bond dipoles very nearly cancel by symmetry', 'The N–F bonds are so polar that they are effectively ionic, and an ionic bond contributes no dipole moment', 'Fluorine lone pairs donate π density back to nitrogen, cancelling the σ polarity of each N–F bond'], a: 0, why: 'A molecular dipole is a vector sum over the whole charge distribution, and the lone pair is one of the vectors. In NH₃ the bond moments run H → N (nitrogen is the negative end) and the lone pair sticks out on the same side of the nitrogen, so the two contributions <b>add</b> to 1.47 D. In NF₃ the bond moments run N → F, pointing down towards the fluorines, directly against the lone pair — they largely cancel, leaving 0.24 D. Geometry cannot be the explanation: NF₃ is <em>more</em> pyramidal than ammonia, with a bond angle of 102° against 107°, so a flattening argument predicts exactly the wrong sign.', misconception: 'The model to discard is "molecular dipole = sum of bond dipoles". A lone pair is a lobe of charge sitting off-centre, and it carries a moment as real as any bond does — often the largest single contribution. Once it is in the sum, the NH₃/NF₃ pair stops being paradoxical: the same lone pair reinforces the bond moments in one molecule and opposes them in the other. Reaching for a symmetry or flattening explanation is the reflex to catch, because the bond angles rule it out before the argument starts.' },
  { id: 'bon-029', tier: 3, topic: 'bonding', skill: ['bonding/polarity', 'bonding/mo-theory'], q: 'Carbon monoxide has a dipole moment of only 0.11 D, and its negative end is the CARBON, though oxygen is far more electronegative. The best account is…', opts: ['The dative character of the triple bond gives formal charges C⁻ and O⁺, and the HOMO is a lone pair sitting mainly on carbon; together these outweigh the σ polarisation towards oxygen', 'The molecule is linear, so its bond dipoles cancel and only a small residual moment survives', 'Carbon is genuinely more electronegative than oxygen here, because the high s character of an sp hybrid raises effective electronegativity', 'The C≡O bond is the strongest known covalent bond, and a very strong bond necessarily shares its electrons evenly'], a: 0, why: 'Count the bonds, then look at where the electrons actually are. Building :C≡O: from neutral atoms needs one of the three pairs to come from oxygen alone, giving formal charges of −1 on carbon and +1 on oxygen; that charge transfer pushes density onto carbon and runs against the σ polarisation that electronegativity produces. The two nearly cancel, which is why the moment is a feeble 0.11 D, and the π back-transfer plus the carbon-based σ HOMO tip the balance so the residue points C⁻→O⁺. The chemistry confirms it: CO binds metals and haem iron through its <b>carbon</b>, the end with the available lone pair.', misconception: 'The cancellation argument is imported from CO₂ and cannot apply here: cancellation needs two or more bond moments related by symmetry, and a heteronuclear diatomic has exactly one bond and no symmetry to cancel it. Behind that lies the wider error of reading dipole direction straight off an electronegativity table. Electronegativity governs how a shared pair is polarised, but a dative pair moves a whole electron\'s worth of density the other way, and in CO those two effects nearly annihilate each other.' },
  { id: 'bon-030', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'N(CH₃)₃ is pyramidal at nitrogen, but N(SiH₃)₃ is planar, and its N–Si bonds are shorter than the sum of the covalent radii. What does this establish?', opts: ['The nitrogen lone pair is delocalised into acceptor orbitals on silicon, which pays for flattening the nitrogen and shortens the N–Si bonds', 'Nothing about bonding: the SiH₃ groups are bulky, and steric repulsion alone forces the molecule open to planar', 'Nitrogen inverts rapidly, so the pyramid is real and only the time-averaged structure looks planar', 'Silicon is more electronegative than carbon, so induction pulls the lone pair away and removes a domain'], a: 0, why: 'VSEPR gives a first guess, and the two pieces of evidence together say the guess fails. If nitrogen simply kept its lone pair, four domains would make it pyramidal like the amine — but a lone pair delocalised onto the silicons is no longer a stereochemically active domain, and the geometry flattens to trigonal planar. The bond lengths are the second, independent line of evidence: a delocalised pair adds π character, so the N–Si bonds come out <b>shorter</b> than a single bond should be, which neither sterics nor induction predicts. Silicon is also less electronegative than carbon, not more, so the induction story has the trend backwards.', misconception: 'Sterics is the reflex explanation and here it is the wrong one — the giveaway is the bond <em>shortening</em>. Steric strain pushes atoms apart; it can flatten a centre, but it never pulls the bonds in below a normal single-bond length. When a geometry change and a bond contraction appear together, the cause is electronic: something is delocalising and adding bond order. The averaging answer fails on the same evidence, since a rapidly inverting pyramid still has ordinary long single bonds.' },
  { id: 'bon-031', tier: 3, topic: 'bonding', skill: 'bonding/lewis-vsepr', q: 'At low temperature the ¹⁹F NMR of SF₄ shows two signals of equal intensity, and the S–F bonds fall into two sets, 165 pm and 155 pm. Which arrangement fits both observations?', opts: ['A seesaw: five domains with the lone pair equatorial, giving two long axial and two short equatorial fluorines', 'A trigonal bipyramid with the lone pair axial, giving one axial fluorine and three equatorial ones', 'A tetrahedron about sulfur with the lone pair delocalised over the cage, so all four fluorines are equivalent', 'A square plane of fluorines with the lone pair above it, so all four fluorines are equivalent'], a: 0, why: 'Two signals of equal intensity means two environments holding two fluorines each — that single fact eliminates three of the four. Sulfur brings six valence electrons and four bonds, so there are five domains; the lone pair takes an <b>equatorial</b> site, where it has only two neighbours at 90°, rather than an axial one with three. That leaves two axial and two equatorial fluorines: the 2:2 pattern the spectrum shows. The bond lengths agree, since the two axial bonds lean away from the fat equatorial lone pair and stretch to 165 pm against 155 pm for the equatorial pair. Warm the sample and Berry pseudorotation averages the sites into one signal, which is why the low temperature was specified.', misconception: 'Putting the lone pair axial is the error, and it predicts a 3:1 spectrum that is never seen. The rule is not arbitrary: in a trigonal bipyramid an axial site has three neighbours at 90°, an equatorial site only two, so the domain that repels hardest — always the lone pair, which is held by one nucleus rather than shared between two — takes the roomier equatorial position. The same rule places both lone pairs of ClF₃ equatorially and makes it T-shaped, and all three of I₃⁻\'s, making it linear.' },
  { id: 'bon-032', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'N₂ and CO are isoelectronic, both of bond order 3, and the C≡O bond (1072 kJ/mol) is the stronger of the two — yet CO binds metal centres readily and N₂ barely at all. Why?', opts: ['CO\'s HOMO is a high-lying lone pair concentrated on carbon and its π* orbitals are low enough to accept back-donation; N₂\'s HOMO lies lower and is shared between two identical atoms', 'CO is polar and N₂ is not, so it is the electrostatic pull of the CO dipole that holds the ligand on the metal', 'One of CO\'s three bonds is dative, so its real bond order is 2, and the weaker bond makes the molecule reactive', 'N₂ holds the strongest bond known at 945 kJ/mol, so it has no electrons to spare for a metal centre'], a: 0, why: 'Bond strength is the wrong axis: it says what it costs to pull the molecule apart, and coordination does not pull the molecule apart. What matters is the frontier orbitals. Isoelectronic species need not have their electrons in the same <em>places</em> — CO is heteronuclear, so its σ HOMO is lopsided onto the carbon and lies high in energy, a lone pair pointed straight at an empty metal orbital, while its π* orbitals sit low enough to take density back from the filled metal d set. That synergic donation and back-donation is what a strong M–CO bond is made of. N₂\'s orbitals are symmetric and lower-lying, so it is both the poorer donor and the poorer acceptor, and N₂ complexes are correspondingly rare and fragile.', misconception: 'Ligand strength is not read off a dipole moment. CO\'s moment is a mere 0.11 D — one of the smallest of any heteronuclear molecule — so an electrostatic account predicts almost no binding at all, and it also gets the direction wrong, since the moment is far too weak to explain why CO always coordinates through carbon. What actually points CO at the metal is the shape and energy of one orbital: the carbon-heavy σ HOMO. Isoelectronic means the same electron count, never the same orbital energies or the same chemistry.' },
  { id: 'bon-033', tier: 3, topic: 'bonding', skill: ['bonding/lewis-vsepr', 'bonding/bond-properties'], q: 'In N,N-dimethylformamide the two N-methyl groups give two separate ¹H NMR singlets at 25 °C which coalesce on heating, and the C–N bond is 133 pm against 147 pm in an amine. What does this establish?', opts: ['The nitrogen lone pair is delocalised into the C=O π*, giving the C–N bond partial double character and a rotation barrier near 80 kJ/mol', 'Inversion at the pyramidal nitrogen is slow on the NMR timescale, so the two methyl groups are frozen into different environments', 'One methyl group hydrogen bonds to the carbonyl oxygen and the other does not, which shifts the two signals apart', 'Rotation about the C=O double bond is restricted, holding the molecule in a single conformation'], a: 0, why: 'The two observations are the same fact seen twice. Delocalising the nitrogen lone pair into the carbonyl π* gives the resonance form with a C=N⁺ and an O⁻, so the C–N linkage carries partial double-bond character — which shortens it to 133 pm (an amine\'s is 147) and, more tellingly, raises a barrier to twisting it. At 25 °C that barrier of roughly 80–90 kJ/mol is high enough to freeze rotation on the NMR timescale, so one methyl is permanently <em>cis</em> to the oxygen and the other <em>trans</em>: two singlets. Heat the sample and rotation outruns the timescale, and the two signals coalesce into one. The C=O also lengthens to about 124 pm from a ketone\'s 120 pm, exactly as the shared π density demands.', misconception: 'Nitrogen inversion is the wrong process on two counts. First, an amide nitrogen is planar precisely <em>because</em> its lone pair is delocalised, so there is no pyramid to invert. Second, even in a genuine amine, inversion has a barrier of only about 25 kJ/mol and is far too fast to be frozen out at room temperature. The process being slowed here is <b>rotation</b> about a bond with partial double character — and the fact that it can be slowed at all is the experimental proof that the delocalisation is real.' },
  { id: 'bon-034', tier: 3, topic: 'bonding', skill: ['bonding/hybridisation', 'bonding/bond-properties'], q: 'The central C–C bond of buta-1,3-diene is 147 pm, well short of ethane\'s 154 pm. In propyne, where no conjugation across that bond is possible, the CH₃–C bond is 146 pm. What follows?', opts: ['Most of the shortening comes from the higher s character of the hybrid orbitals joined, with π delocalisation contributing a smaller extra amount', 'Delocalisation equalises the two C–C linkages in butadiene at about 1.5 bonds each, as it does in benzene', 'Bond length is fixed by bond order alone, so butadiene\'s central bond must have an order of about 1.2', 'The propyne figure is irrelevant, since it is the length of a triple bond and not of the single bond next to it'], a: 0, why: 'The propyne number is a control experiment, and it is what makes this an argument rather than a story. Propyne\'s CH₃–C bond joins an sp³ carbon to an sp carbon and measures 146 pm — as short as butadiene\'s central bond — yet no conjugation can cross it. So the bulk of the contraction must come from the property both cases share: hybrids with more s character are more compact, and both butadiene\'s central carbons (sp²) and propyne\'s alkyne carbon (sp) exceed ethane\'s sp³. Conjugation is real but second-order here, and butadiene\'s own numbers show it: the C1=C2 bond is 134 pm, essentially ethene\'s 134, so the π system has not redistributed itself much at all.', misconception: 'Benzene is the wrong model to carry into every conjugated system. Its equal 140 pm bonds come from its <em>symmetry</em> — a ring of six equivalent carbons whose two Kekulé structures are related by a rotation — and no open chain has that. Butadiene keeps a clear alternation, 134 and 147 pm, so it is a diene with a slightly shortened link between the double bonds, not a chain of one-and-a-half bonds. When an unexpectedly short bond appears, check hybridisation before invoking delocalisation: it is the larger effect more often than students expect.' },
  { id: 'bon-035', tier: 3, topic: 'bonding', skill: 'bonding/mo-theory', q: 'Cyclopenta-1,3-diene has a pKa of about 16, on a par with water, while cyclohepta-1,3,5-triene comes in near 36 — despite the larger ring offering more π system to spread the charge. What does this show?', opts: ['Deprotonation makes the cyclopentadienyl anion aromatic, six π electrons over five equivalent carbons, while the seven-membered anion would hold eight π electrons and is antiaromatic', 'The seven-membered ring is the aromatic one — tropylium — so cycloheptatriene is really the stronger acid and the two pKa values have been quoted the wrong way round', 'Charge on the smaller ring simply sits closer to more nuclei, so a compact carbanion is always the better stabilised of the two', 'The extra sp³ CH₂ groups of the larger ring push electron density inductively onto its carbanion and destabilise it'], a: 0, why: 'Acidity is a statement about the conjugate base, so build both anions. Removing the sp³ proton from cyclopentadiene leaves a carbanion whose lone pair joins the two π bonds in a planar, fully conjugated ring: six π electrons over five carbons, a Hückel 4n+2 count, and the ring becomes aromatic with all five C–C bonds at 140 pm. Removing the corresponding proton from cycloheptatriene gives a planar conjugated ring with <b>eight</b> π electrons — a 4n count, which is destabilising, not stabilising. Twenty orders of magnitude in acidity separate them, and the extra delocalisation belongs to the ring that ionises worse: delocalisation is not automatically a stabiliser.', misconception: 'The aromatic seven-membered species is the tropylium <em>cation</em>, C₇H₇⁺, which is why cycloheptatriene loses a hydride so readily; its anion is a different species with two more electrons and the opposite Hückel count. Behind the mix-up sits a broader habit: judging stabilisation by how far the charge can spread, or by counting resonance structures. Both anions delocalise across their whole ring, so that measure cannot tell them apart — only the π electron count against 4n + 2 can, and it is worth checking the sign of the charge before deciding which ion the rule is being applied to.' },
];

export const STOICH_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'sto-001', topic: 'stoich', skill: 'stoich/mole-concept', q: 'Molar mass of water?', opts: ['16 g/mol', '18 g/mol', '20 g/mol', '10 g/mol'], a: 1, why: '2(1.0) + 16.0 = 18.0 g/mol.' },
  { id: 'sto-002', topic: 'stoich', skill: 'stoich/mole-concept', q: 'One mole contains how many particles?', opts: ['6.022×10²³', '6.022×10²²', '3.011×10²³', '1.66×10⁻²⁴'], a: 0, why: 'Avogadro\'s number, 6.022×10²³ — defined by carbon-12.' },
  { id: 'sto-003', topic: 'stoich', skill: 'stoich/mole-concept', q: 'How many moles are in 44 g of CO₂?', opts: ['0.5', '44', '2', '1'], a: 3, why: 'n = m/M = 44 g ÷ 44 g/mol = 1 mol.' },
  { id: 'sto-004', topic: 'stoich', skill: 'stoich/mole-concept', q: 'Balance: __H₂ + __O₂ → __H₂O', opts: ['1, 1, 1', '2, 2, 1', '2, 1, 2', '1, 2, 2'], a: 2, why: '2H₂ + O₂ → 2H₂O balances 4 H and 2 O on each side.' },
  { id: 'sto-005', topic: 'stoich', skill: 'stoich/solution-conc', q: 'Molarity of 1 mol of NaCl dissolved to make 2 L of solution?', opts: ['2 M', '0.5 M', '1 M', '0.25 M'], a: 1, why: 'M = n/V = 1/2 = 0.5 mol/L.' },
  // ---- olympiad ----
  { id: 'sto-006', topic: 'stoich', skill: 'stoich/limiting-reagent', q: '4 mol H₂ react with 1 mol O₂ (2H₂ + O₂ → 2H₂O). How much water forms?', opts: ['2 mol', '4 mol', '1 mol', '3 mol'], a: 0, why: 'Ratios: H₂ 4/2 = 2, O₂ 1/1 = 1 → O₂ limiting, extent = 1 → 2 mol H₂O, 2 mol H₂ left over.', misconception: 'Limiting reagent is decided by <em>mole ratio</em>, never by which reactant you have less of. Here there are 4 mol H₂ and only 1 mol O₂, yet dividing by the coefficients (4/2 = 2 versus 1/1 = 1) shows the oxygen runs out first. Comparing raw amounts — or worse, raw masses — is the single most common stoichiometry error, and it produces exactly the "4 mol" answer.' },
  { id: 'sto-007', topic: 'stoich', skill: 'stoich/net-ionic', q: 'Net ionic equation for mixing HCl(aq) and NaOH(aq)?', opts: ['HCl + NaOH → NaCl + H₂O', 'H⁺ + NaOH → Na⁺ + H₂O', 'Na⁺ + Cl⁻ → NaCl', 'H⁺ + OH⁻ → H₂O'], a: 3, why: 'Strong electrolytes split into ions; Na⁺ and Cl⁻ are spectators. Every strong acid + strong base gives this same net equation.' },
  { id: 'sto-008', topic: 'stoich', skill: 'stoich/net-ionic', q: 'Which salt is soluble in water?', opts: ['BaSO₄', 'AgCl', 'K₂CO₃', 'PbI₂'], a: 2, why: 'Group 1 and NH₄⁺ salts are ALWAYS soluble — that rule overrides "carbonates are insoluble."', misconception: 'The solubility rules are a <em>ranked</em> list, not a set of equal statements. "Group 1 and ammonium salts are always soluble" sits above "carbonates are insoluble", so K₂CO₃ dissolves despite being a carbonate. Applying the rules in the order they appear on the page, rather than by precedence, is what makes this question look ambiguous when it is not.' },
  { id: 'sto-009', topic: 'stoich', skill: 'stoich/empirical-formula', q: 'A compound is 40.0% C, 6.7% H, 53.3% O. Empirical formula?', opts: ['CHO', 'CH₂O', 'C₂H₄O', 'CH₃O'], a: 1, why: 'Per 100 g: C 3.33, H 6.7, O 3.33 mol → 1:2:1 → CH₂O.' },
  { id: 'sto-010', topic: 'stoich', skill: 'stoich/solution-conc', q: 'You need 0.5 M HCl from 6.0 M stock. Dilute 50 mL of stock to…', opts: ['300 mL', '1200 mL', '150 mL', '600 mL'], a: 3, why: 'M₁V₁ = M₂V₂ → V₂ = 6.0 × 50 / 0.5 = 600 mL total.', misconception: 'M₁V₁ = M₂V₂ gives the FINAL total volume, not the volume of water to add. Diluting 50 mL of 6.0 M stock to 0.5 M means making the solution up to 600 mL — which is adding about 550 mL of water, not 600. On a real bench this is the difference between a correct standard and one that is 8% wrong.' },
  { id: 'sto-011', tier: 3, topic: 'stoich', skill: 'stoich/empirical-formula', q: '2.50 g of CuSO₄·xH₂O leaves 1.60 g CuSO₄ (M = 159.6) after heating. x = ?', opts: ['5', '3', '7', '10'], a: 0, why: 'CuSO₄: 1.60/159.6 = 0.0100 mol; H₂O: 0.90/18 = 0.050 mol → x = 5 (blue vitriol, CuSO₄·5H₂O).', misconception: 'x is a MOLE ratio, not a mass ratio: 0.90 g of water against 1.60 g of salt looks like roughly 0.5, but water is nine times the lighter formula unit, so the mole ratio is 0.050 : 0.0100 = 5 : 1. Dividing the wrong way round — salt per water — is the other half of this trap, and it always gives an x below 1.', why2: 'Check by rebuilding the formula rather than trusting the division. CuSO₄·5H₂O has M = 159.6 + 5(18.0) = 249.6 g/mol, so the 2.50 g sample is 2.50/249.6 = 0.0100 mol — exactly the amount of CuSO₄ left behind. Any candidate x can be tested in one line this way (x = 3 would need M = 213.6 and predict 1.87 g of residue, x = 7 would need 285.6 and predict 1.40 g), and only the right one reproduces both masses at once.' },
  { id: 'sto-012', topic: 'stoich', skill: 'stoich/mole-concept', q: 'Volume of O₂ at STP (22.4 L/mol) needed to burn 1 mol CH₄ completely?', opts: ['22.4 L', '44.8 L', '11.2 L', '67.2 L'], a: 1, why: 'CH₄ + 2O₂ → CO₂ + 2H₂O needs 2 mol O₂ = 44.8 L.' },
  { id: 'sto-013', topic: 'stoich', skill: 'redox/balancing', q: 'In acidic MnO₄⁻ + Fe²⁺ titration, the mole ratio MnO₄⁻ : Fe²⁺ is…', opts: ['1:1', '1:3', '1:5', '2:5'], a: 2, why: 'Mn(+7)→Mn²⁺ gains 5 e⁻; each Fe²⁺→Fe³⁺ loses 1 → 1 permanganate oxidizes 5 iron(II). Self-indicating (purple → colorless).' },
  { id: 'sto-014', tier: 3, topic: 'stoich', skill: 'stoich/solution-conc', q: '25.0 mL of H₂SO₄ needs 40.0 mL of 0.100 M NaOH. [H₂SO₄] = ?', opts: ['0.16 M', '0.32 M', '0.04 M', '0.08 M'], a: 3, why: 'n(NaOH) = 0.00400 mol; diprotic → n(acid) = 0.00200 mol; ÷ 0.0250 L = <b>0.0800 M</b>. Forgetting the 2 gives the 0.16 trap.', misconception: 'A diprotic acid supplies two protons per molecule, so moles of base is not moles of acid. n(NaOH) = 4.00 mmol → n(H₂SO₄) = 2.00 mmol → 0.0800 M. Skipping the factor of two gives 0.16 M, exactly double, and it is the distractor placed there for that reason. Write the balanced neutralisation equation before dividing, every time.' , why2: 'Count protons, not molecules. The titration is H⁺ + OH⁻ → H₂O and nothing else, so start from what the base delivers: 40.0 mL × 0.100 M = 4.00 mmol OH⁻, therefore 4.00 mmol H⁺ was present. Each H₂SO₄ carries two of them, so the flask held 2.00 mmol of acid in 25.0 mL = <b>0.0800 M</b>. If the arithmetic ever feels ambiguous, settle the direction first: a diprotic acid needs <em>more</em> base per mole, so a fixed amount of base accounts for <em>fewer</em> moles of acid — the answer has to come out below 0.16 M, not above it.' },
  { id: 'sto-015', topic: 'stoich', skill: 'stoich/percent-composition', q: 'Mass percent of nitrogen in NH₄NO₃ (M = 80)?', opts: ['35%', '17.5%', '28%', '52%'], a: 0, why: 'Two N per formula: 28/80 = 35%. Both nitrogens count!' },
  { id: 'sto-016', topic: 'stoich', skill: 'stoich/empirical-formula', q: 'Empirical formula CH₂, molar mass 56 g/mol. Molecular formula?', opts: ['C₂H₄', 'C₄H₈', 'C₃H₆', 'C₅H₁₀'], a: 1, why: '56 / 14 = 4 → (CH₂)₄ = C₄H₈ (butene or cyclobutane).' },
  { id: 'sto-017', tier: 3, topic: 'stoich', skill: 'stoich/mole-concept', q: 'Which sample contains the MOST atoms?', opts: ['1 g of O₂', '1 g of He', '1 g of H₂', '1 g of Ne'], a: 2, why: '1 g H₂ = 0.5 mol molecules = 1 mol atoms. He: 0.25 mol atoms. Lightest particles win.', misconception: 'Equal <em>masses</em> are not equal amounts, and molecules are not atoms — this question needs both conversions. One gram of H₂ is 0.50 mol of molecules but 1.0 mol of atoms; one gram of He is only 0.25 mol of atoms. The lightest particle always wins a "most particles per gram" comparison, and forgetting the diatomic doubling is what makes it feel like a tie.' },
  { id: 'sto-018', topic: 'stoich', skill: 'stoich/solution-conc', q: 'Mix 100 mL of 1.0 M NaCl with 300 mL of 2.0 M NaCl. Final concentration?', opts: ['1.5 M', '1.25 M', '2.0 M', '1.75 M'], a: 3, why: 'Total moles (0.10 + 0.60) ÷ total volume 0.400 L = 1.75 M — a weighted average, closer to the bigger portion.', misconception: 'Mixing two solutions gives a <em>weighted</em> average, not the midpoint of the two concentrations. Here 100 mL of 1.0 M and 300 mL of 2.0 M give (0.10 + 0.60)/0.400 = 1.75 M, pulled toward the larger portion — "1.5 M" is the arithmetic mean and it ignores the volumes entirely. Always go back to moles and total volume rather than averaging labels.' },
  { id: 'sto-019', topic: 'stoich', skill: 'stoich/net-ionic', q: 'Net ionic equation for Na₂CO₃(aq) + excess HCl(aq)?', opts: ['CO₃²⁻ + 2H⁺ → H₂O + CO₂', 'Na⁺ + Cl⁻ → NaCl', 'CO₃²⁻ + HCl → HCO₃⁻ + Cl⁻', 'H⁺ + OH⁻ → H₂O'], a: 0, why: 'Carbonate + strong acid fizzes CO₂. Na⁺ and Cl⁻ spectate.' },
  { id: 'sto-020', topic: 'stoich', skill: 'redox/oxidation-states', q: 'Oxidation state of Cr in Cr₂O₇²⁻?', opts: ['+6', '+3', '+7', '+4'], a: 0, why: '2x + 7(−2) = −2 → x = +6. Orange dichromate; reduction to green Cr³⁺ is the classic color change.' },
  { id: 'sto-021', topic: 'stoich', skill: 'redox/oxidation-states', q: 'Which reaction is a disproportionation?', opts: ['Zn + Cu²⁺ → Zn²⁺ + Cu', 'AgNO₃ + NaCl → AgCl + NaNO₃', '2H₂ + O₂ → 2H₂O', 'Cl₂ + 2OH⁻ → Cl⁻ + ClO⁻ + H₂O'], a: 3, why: 'Chlorine (0) is simultaneously reduced to Cl⁻ (−1) and oxidized to ClO⁻ (+1) — one element going both ways.' },
  { id: 'sto-022', topic: 'stoich', skill: 'stoich/solution-conc', q: '2 mg of fluoride in 1 kg of water is a concentration of…', opts: ['2 ppb', '0.2%', '2 ppm', '2 M'], a: 2, why: 'ppm = mg solute per kg solution — dilute aqueous solutions make mg/L ≈ ppm.' },
  { id: 'sto-023', topic: 'stoich', skill: 'stoich/solution-conc', q: 'Which measurement is needed to convert molarity to molality?', opts: ['temperature', 'solution density', 'molar mass of solute only', 'pressure'], a: 1, why: 'Molality needs kg of SOLVENT; from molarity you know volume of solution — density bridges them (then subtract the solute\'s mass).', misconception: 'Molarity is per litre of <em>solution</em>; molality is per kilogram of <em>solvent</em>. Converting between them therefore needs the density (to turn the solution\'s volume into its mass) and then the solute\'s mass subtracted off to leave the solvent. Molar mass alone is not enough, and in dilute aqueous solution the two are numerically close only because the density is near 1 — an accident of water that fails for every other solvent.' },
  { id: 'sto-024', topic: 'stoich', skill: 'stoich/mole-concept', q: '0.5 mol of Al reacts via 2Al + 6HCl → 2AlCl₃ + 3H₂. Moles of H₂?', opts: ['0.75', '0.5', '1.0', '1.5'], a: 0, why: 'Ratio 3 H₂ : 2 Al → 0.5 × 3/2 = 0.75 mol.' },
  { id: 'sto-025', tier: 3, topic: 'stoich', skill: 'stoich/percent-composition', q: 'A 1.00 g mixture of NaCl and KCl contains 0.60 g NaCl. Mass % Cl⁻ in the mixture ≈ ?', opts: ['45%', '35%', '60%', '55%'], a: 3, why: 'Cl from NaCl: 0.60 × 35.5/58.5 = 0.364 g; from KCl: 0.40 × 35.5/74.6 = 0.190 g → 0.554 g ≈ 55%.', misconception: 'Each salt has its own chloride mass fraction — 35.5/58.5 = 60.7% for NaCl but only 35.5/74.6 = 47.6% for KCl — so the mixture\'s figure has to be a mass-weighted blend of the two, never one of them and never a plain average. Answering 60% is quoting NaCl\'s own chloride fraction (or simply echoing the 0.60 g of NaCl) as if it described the whole sample.' },
];

export const THERMO1_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'th1-001', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'An exothermic reaction has…', opts: ['ΔH > 0', 'ΔH = 0', 'ΔH < 0', 'ΔS < 0'], a: 2, why: 'Exothermic = releases heat = enthalpy of the system falls.' },
  { id: 'th1-002', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Units of specific heat capacity?', opts: ['J/mol', 'g·K/J', 'J/K only', 'J/g·K'], a: 3, why: 'c = energy per gram per degree: q = mcΔT.' },
  { id: 'th1-003', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Heat to warm 100 g of water (c = 4.18) by 10 °C?', opts: ['4180 J', '418 J', '41.8 J', '41800 J'], a: 0, why: 'q = mcΔT = 100 × 4.18 × 10 = 4180 J ≈ 4.2 kJ.' },
  { id: 'th1-004', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Which process is endothermic?', opts: ['freezing water', 'melting ice', 'condensing steam', 'burning methane'], a: 1, why: 'Melting absorbs heat to break the lattice. Freezing/condensing release it.' },
  { id: 'th1-005', topic: 'thermo1', skill: 'thermo/entropy', q: 'Heat flows spontaneously from…', opts: ['cold to hot', 'high pressure to low', 'hot to cold', 'solid to gas'], a: 2, why: 'Down the temperature gradient, until thermal equilibrium — the everyday face of the second law.' },
  // ---- olympiad ----
  { id: 'th1-006', topic: 'thermo1', skill: 'thermo/state-functions', q: 'A gas expands against constant external pressure. The sign of w for the SYSTEM is…', opts: ['positive', 'depends on temperature', 'zero', 'negative'], a: 3, why: 'w = −PₑₓₜΔV; expansion (ΔV > 0) means the system spends energy pushing the surroundings back.', misconception: 'The sign of w follows the convention w = −P_ext ΔV, written from the <em>system\'s</em> point of view. A gas that expands does work on its surroundings and loses energy, so w is negative; a gas being compressed has w positive. Reading "the gas did work, so w is positive" mixes up who is doing the work on whom, and it flips the sign of every subsequent ΔU.' },
  { id: 'th1-007', topic: 'thermo1', skill: 'thermo/state-functions', q: 'A bomb calorimeter (rigid, sealed) directly measures…', opts: ['ΔU', 'ΔH', 'ΔG', 'ΔS'], a: 0, why: 'Constant volume → no PV work → qᵥ = ΔU. Coffee-cup (constant P) gives ΔH.', misconception: 'A bomb calorimeter is rigid, so ΔV = 0 and no PV work is possible: what it measures is q_v = ΔU. A coffee-cup calorimeter is open to the atmosphere, constant pressure, and measures q_p = ΔH. They differ by Δn(gas)RT — small, but not zero — so quoting a bomb-calorimeter result as ΔH without correcting it is a real error, not a rounding one.' },
  { id: 'th1-008', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Which species has ΔH°f = 0?', opts: ['O(g)', 'Br₂(l)', 'CO₂(g)', 'C(diamond)'], a: 1, why: 'Standard state of bromine is LIQUID Br₂. O(g) isn\'t standard (O₂ is); graphite, not diamond, is carbon\'s reference.', misconception: 'ΔH°f = 0 applies only to an element in <em>its</em> standard state — the form that is actually stable at 1 bar and 25 °C. That is Br₂(l), not Br₂(g); graphite, not diamond; O₂(g), not O(g). Diamond has ΔH°f = +1.9 kJ/mol, and treating any elemental form as a zero is the error this question is built around.' },
  { id: 'th1-009', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Heating 10 g of ice at 0 °C to water at 10 °C: which step absorbs more heat?', opts: ['about equal', 'warming the water', 'melting the ice', 'cannot tell'], a: 2, why: 'Melting: 334 × 10 = 3340 J vs warming: 4.18 × 10 × 10 = 418 J. Phase changes dominate heating curves.' },
  { id: 'th1-010', topic: 'thermo1', skill: 'thermo/bond-energies', q: 'A reaction is exothermic when…', opts: ['bonds formed are stronger than broken', 'bonds broken are stronger than formed', 'more bonds break than form', 'products have more enthalpy'], a: 0, why: 'Breaking always costs, forming always pays; stronger new bonds → net release.', misconception: 'Bond breaking is always endothermic and bond making is always exothermic — there is no such thing as an exothermic bond break. What decides the sign of a reaction\'s ΔH is the <em>balance</em>: if the bonds formed are stronger than those broken, more comes back than went out. "More bonds break than form" is not the criterion, and a reaction can be strongly exothermic with equal numbers of bonds on both sides.' },
  { id: 'th1-011', tier: 3, topic: 'thermo1', skill: 'thermo/hess', q: 'ΔH°f: CO₂ −393.5, H₂O(l) −285.8, CH₄ −74.8 kJ/mol. ΔH° for CH₄ + 2O₂ → CO₂ + 2H₂O(l)?', opts: ['−604 kJ', '−820 kJ', '−965 kJ', '−890 kJ'], a: 3, why: 'Σproducts − Σreactants = (−393.5 − 571.6) − (−74.8) = <b>−890.3 kJ</b>. O₂ contributes 0.', misconception: 'The coefficient multiplies ΔH°f before the sum and the physical state changes the value — miss the 2 on water and you get −604, use gaseous water instead of liquid and you get −820. Reactants are SUBTRACTED, so ΔH°f(CH₄) enters as +74.8, and O₂ as an element in its standard state contributes exactly zero rather than being left out by accident.' },
  { id: 'th1-012', tier: 3, topic: 'thermo1', skill: 'thermo/state-functions', q: 'For N₂ + 3H₂ → 2NH₃ at 298 K, how do ΔH and ΔU compare?', opts: ['ΔH = ΔU', 'ΔH > ΔU', 'ΔH < ΔU', 'cannot compare'], a: 2, why: 'ΔH = ΔU + Δn(gas)RT and Δn = −2 → ΔH is LOWER by 2RT ≈ 5 kJ. Gas moles shrink, the atmosphere does work on the system.', misconception: 'ΔH and ΔU differ whenever the number of gas moles changes: ΔH = ΔU + Δn(gas)RT. For N₂ + 3H₂ → 2NH₃, Δn = −2, so ΔH is about 5 kJ/mol <em>lower</em> than ΔU at 298 K — the surroundings do work on the shrinking system. Treating the two as interchangeable is safe only when Δn(gas) = 0.' , why2: 'Watch the piston rather than the formula. ΔU is the energy the molecules themselves gained or lost; ΔH also pays for the work of shoving the atmosphere out of the way. Here 4 mol of gas become 2, so at constant pressure the vessel shrinks and the <em>atmosphere does work on the system</em>, +2RT of it. That donated work is energy the reaction does not have to supply, so the heat released at constant pressure exceeds the drop in internal energy: ΔH = ΔU − 2RT ≈ ΔU − 5 kJ, i.e. <b>ΔH &lt; ΔU</b>. The rule of thumb: gas moles shrink → surroundings push in → ΔH is the more negative of the two.' },
  { id: 'th1-013', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'During boiling, the temperature of water stays at 100 °C because added heat…', opts: ['is destroyed', 'goes into breaking intermolecular attractions', 'speeds up molecules equally', 'escapes the pot'], a: 1, why: 'Energy raises potential energy (separating molecules), not kinetic energy — hence flat plateaus on heating curves.', misconception: 'Heat added at a phase change does not raise the temperature, and this is not a failure of the thermometer. The energy goes into <em>potential</em> energy, pulling molecules apart against their intermolecular attractions, while the average kinetic energy — which is what temperature measures — stays put. This is why heating curves have flat plateaus and why steam at 100 °C burns far worse than water at 100 °C.' },
  { id: 'th1-014', tier: 3, topic: 'thermo1', skill: 'thermo/enthalpy', q: '50 g of metal at 100 °C dropped into 100 g water at 20 °C settles at 25 °C. c(metal) ≈ ?', opts: ['0.56 J/g·K', '4.18 J/g·K', '1.12 J/g·K', '0.24 J/g·K'], a: 0, why: 'q(water) = 100×4.18×5 = 2090 J = −q(metal) = 50×c×75 → c = 2090/3750 ≈ <b>0.56</b>.', misconception: 'The two bodies share a final temperature but not a ΔT: the metal falls 100 → 25 = 75 K while the water rises 20 → 25 = 5 K. Using the water\'s 5 K for the metal, or taking the metal\'s drop as 100 → 20 = 80 K, is where the wrong values come from — and 4.18 belongs to the water, so any metal specific heat near or above it should read as impossible before you write it down.' },
  { id: 'th1-015', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Why is ΔH(vaporization) much larger than ΔH(fusion)?', opts: ['gases are hotter', 'it isn\'t — they\'re similar', 'liquids have no IMFs', 'vaporization must fully separate molecules; melting only loosens them'], a: 3, why: 'Melting keeps neighbors in contact (~10% IMF loss); boiling breaks essentially ALL intermolecular attractions. Water: 6 vs 40.7 kJ/mol.' },
  { id: 'th1-016', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Standard enthalpy of formation refers to forming 1 mol of compound from…', opts: ['its ions', 'its atoms in the gas phase', 'its elements in standard states', 'any convenient reactants'], a: 2, why: 'From elements as they exist at 1 bar, 25 °C: C(graphite), O₂(g), etc. From gaseous ATOMS would be atomization — different quantity.' },
  { id: 'th1-017', topic: 'thermo1', skill: 'thermo/hess', q: 'Hess\'s law works because enthalpy is…', opts: ['always negative', 'a state function', 'proportional to temperature', 'a path function'], a: 1, why: 'State functions depend only on start and end points — any route between them sums to the same ΔH.' },
  { id: 'th1-018', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Combustion of H₂ to H₂O(l) vs to H₂O(g): which releases more heat?', opts: ['to H₂O(l)', 'to H₂O(g)', 'identical', 'depends on pressure'], a: 0, why: 'Liquid is lower in enthalpy — you additionally collect the heat of condensation (44 kJ/mol). This is the HHV/LHV fuel distinction.', misconception: 'Burning to liquid water releases more heat than burning to steam, by the enthalpy of condensation (about 44 kJ per mole of water). That is exactly the higher/lower heating value distinction quoted for fuels: the HHV assumes the water in the exhaust is condensed and its heat recovered, the LHV assumes it leaves as vapour. Writing "H₂O" in a combustion equation without deciding its state leaves ΔH ambiguous by tens of kJ.' },
  { id: 'th1-019', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Coastal cities have milder climates than inland ones mainly because water…', opts: ['reflects sunlight', 'is transparent', 'evaporates constantly', 'has a very high specific heat'], a: 3, why: 'c = 4.18 J/g·K is enormous — oceans absorb and release huge amounts of heat with little temperature change, buffering the coast.' },
  { id: 'th1-020', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Enthalpy of neutralization of any strong acid + strong base is ≈ −57 kJ/mol because…', opts: ['all acids are identical', 'water has high heat capacity', 'salts are stable', 'the net reaction is always H⁺ + OH⁻ → H₂O'], a: 3, why: 'Strong species are fully dissociated — the only chemistry is H⁺ + OH⁻. Weak acids give slightly less (ionization costs energy first).' },
  { id: 'th1-021', topic: 'thermo1', skill: 'thermo/state-functions', q: 'In which process is w = 0?', opts: ['reaction in a rigid sealed vessel', 'gas compressed by a piston', 'gas expands against 1 atm', 'gas expands a balloon'], a: 0, why: 'No volume change → no PV work. All energy exchange is heat: ΔU = q.' },
  { id: 'th1-022', topic: 'thermo1', skill: 'thermo/hess', q: 'ΔH for a reverse reaction is…', opts: ['the same as forward', 'sign-flipped', 'zero', 'halved'], a: 1, why: 'State function: going back retraces the enthalpy change exactly, with opposite sign. Multiply the equation → multiply ΔH too.' },
  { id: 'th1-023', topic: 'thermo1', skill: 'thermo/bond-energies', q: 'Using average bond enthalpies is only strictly valid for reactions…', opts: ['in solution', 'at 0 K', 'in the gas phase', 'with catalysts'], a: 2, why: 'Tabulated values are gas-phase averages; condensed phases add lattice/IMF terms the bond sum ignores.', misconception: 'Tabulated bond enthalpies are <em>averages over many molecules</em>, and they apply to the gas phase only. Use them on a reaction in solution and the answer silently ignores every solvation and lattice term, which can be larger than the bond terms themselves. A bond-enthalpy estimate is a sanity check, never a substitute for ΔH°f data when the data exist.' },
  { id: 'th1-024', topic: 'thermo1', skill: 'thermo/enthalpy', q: 'Which requires the input of energy?', opts: ['H(g) + H(g) → H₂(g)', 'Cl(g) + e⁻ → Cl⁻(g)', 'Na⁺(g) + Cl⁻(g) → NaCl(s)', 'Na(g) → Na⁺(g) + e⁻'], a: 3, why: 'Ionization energy is always positive (endothermic). The other three release energy (EA of Cl, lattice energy, bond formation).' },
  { id: 'th1-025', tier: 3, topic: 'thermo1', skill: 'thermo/hess', q: 'Given C + O₂ → CO₂ (ΔH = −393.5 kJ) and 2CO + O₂ → 2CO₂ (ΔH = −566.0 kJ), ΔH for C + ½O₂ → CO is…', opts: ['−110.5 kJ', '−172.5 kJ', '+110.5 kJ', '−676.5 kJ'], a: 0, why: 'Keep the first; reverse HALF the second (+283.0). Sum: −393.5 + 283.0 = <b>−110.5 kJ</b>. The classic Hess manipulation — you can\'t measure CO formation directly (some C always burns fully).', misconception: 'ΔH belongs to the equation AS WRITTEN, so scaling the equation scales ΔH with it: halving 2CO + O₂ → 2CO₂ turns −566.0 into −283.0, and only then does reversing flip it to +283.0. Reversing without halving gives −172.5; halving without reversing gives −676.5. Both come from treating −566.0 as a fixed property of the chemistry rather than of the balanced equation.' },
];

export const THERMO2_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'th2-001', topic: 'thermo2', skill: 'thermo/entropy', q: 'Entropy is best described as a measure of…', opts: ['the heat content', 'the average bond strength', 'the absolute temperature', 'accessible microstates'], a: 3, why: 'S = k ln W — how many microscopic arrangements produce the same macroscopic state.', misconception: 'Entropy is not "disorder", and that word will mislead you on a real problem. It counts how many microscopic arrangements are consistent with what you can measure — a matter of <em>how the energy and particles can be distributed</em>, not how untidy something looks. The tell: dissolving a gas in water has ΔS &lt; 0, and so does dissolving many salts, even though the neat crystal visibly breaks up. Count states, don\'t picture mess.' },
  { id: 'th2-002', topic: 'thermo2', skill: 'thermo/entropy', q: 'Which phase of water has the highest entropy?', opts: ['ice', 'liquid', 'steam', 'all equal'], a: 2, why: 'Gas ≫ liquid > solid: gas molecules roam the whole container.' },
  { id: 'th2-003', topic: 'thermo2', skill: 'thermo/gibbs', q: 'A reaction is spontaneous when…', opts: ['ΔG > 0', 'ΔG < 0', 'ΔH < 0 always', 'ΔS < 0'], a: 1, why: 'Negative Gibbs energy is THE criterion (at constant T, P). Exothermic helps but isn\'t required.' },
  { id: 'th2-004', topic: 'thermo2', skill: 'thermo/entropy', q: 'The sign of ΔS for melting is…', opts: ['positive', 'negative', 'zero', 'depends on the substance'], a: 0, why: 'Solid → liquid frees the molecules to rearrange: more microstates.' },
  { id: 'th2-005', topic: 'thermo2', skill: 'thermo/entropy', q: 'The third law says S = 0 for…', opts: ['any ideal gas at STP', 'pure elements at 25 °C', 'liquid water at 0 °C', 'a perfect crystal at 0 K'], a: 3, why: 'One perfect arrangement, W = 1 → S = k ln 1 = 0. This anchors ABSOLUTE entropies.' },
  // ---- olympiad ----
  { id: 'th2-006', topic: 'thermo2', skill: 'thermo/entropy', q: 'Which reaction has ΔS > 0?', opts: ['N₂(g) + 3H₂(g) → 2NH₃(g)', 'H₂O(g) → H₂O(l), condensing', '2H₂O₂(l) → 2H₂O(l) + O₂(g)', 'CO₂(g) → CO₂(s), depositing'], a: 2, why: 'Count gas moles: liquid → liquid + GAS creates gas from none. The others reduce or condense.' },
  { id: 'th2-007', tier: 3, topic: 'thermo2', skill: 'thermo/gibbs', q: 'ΔH < 0 and ΔS < 0. The reaction is spontaneous…', opts: ['at all temperatures', 'only at LOW temperature', 'never', 'only at HIGH temperature'], a: 1, why: 'ΔG = ΔH − TΔS: the favorable ΔH wins at small T; the unfavorable −TΔS takes over above T = ΔH/ΔS.', misconception: 'ΔH &lt; 0 with ΔS &lt; 0 is not "never spontaneous" — it is spontaneous at LOW temperature only. In ΔG = ΔH − TΔS the −TΔS term is unfavourable and grows with T, so the reaction turns off above T = ΔH/ΔS rather than switching on. Two of the four sign quadrants are temperature-dependent, and getting the direction of the switch backwards is the usual error.' },
  { id: 'th2-008', topic: 'thermo2', skill: 'thermo/gibbs', q: 'At equilibrium, which quantity equals zero?', opts: ['ΔG', 'ΔG°', 'ΔS', 'K'], a: 0, why: 'ΔG = 0 — no net driving force. ΔG° is a fixed constant (zero only if K = 1).', misconception: 'ΔG° and ΔG are different quantities, and the degree symbol is doing real work. ΔG° is a single fixed number for the reaction — everything at standard states — and it fixes K through ΔG° = −RT ln K. ΔG is the driving force <em>right now</em>, at whatever Q the mixture currently sits at: ΔG = ΔG° + RT ln Q. So a reaction with ΔG° > 0 is <em>not</em> "impossible"; it simply has K &lt; 1 and still runs forward until Q reaches K.' },
  { id: 'th2-009', topic: 'thermo2', skill: 'thermo/gibbs', q: 'If ΔG° = 0 at 298 K, then K is…', opts: ['0', 'negative', '∞', '1'], a: 3, why: 'ΔG° = −RT ln K → ln K = 0 → K = 1.' },
  { id: 'th2-010', topic: 'thermo2', skill: 'thermo/entropy', q: 'Highest standard molar entropy at 298 K?', opts: ['He(g)', 'C₂H₆(g)', 'H₂O(l)', 'NaCl(s)'], a: 1, why: 'Gas beats liquid beats solid; among gases, more atoms = more rotations/vibrations to store energy in.', misconception: 'Phase is the first thing to check for entropy, but among substances in the <em>same</em> phase it decides nothing. Ethane and helium are both gases; C₂H₆ has far more entropy (229 versus 126 J/mol·K) because a polyatomic molecule has rotations and vibrations to store energy in, and a monatomic gas has none. More atoms per molecule means more ways to distribute the same energy.' },
  { id: 'th2-011', tier: 3, topic: 'thermo2', skill: 'thermo/entropy', q: 'ΔH(vap) of water = 40.7 kJ/mol at 373 K. ΔS(vap) ≈ ?', opts: ['40.7 J/mol·K', '9.2 J/mol·K', '109 J/mol·K', '373 J/mol·K'], a: 2, why: 'At the normal bp the phases are in equilibrium: ΔG = 0 → ΔS = ΔH/T = 40700/373 ≈ <b>109 J/mol·K</b>.', misconception: 'ΔS = ΔH/T is legitimate here only because the two phases are at equilibrium at the normal boiling point (ΔG = 0), and it is only correct in consistent units — 40.7 kJ must become 40 700 J. Dividing the other way round, T/ΔH, gives 9.2, and quoting 40.7 J/mol·K is copying the enthalpy value across as though entropy shared its scale. Trouton\'s rule says the answer should land near 85–110 J/mol·K for almost any liquid.' },
  { id: 'th2-012', tier: 3, topic: 'thermo2', skill: 'thermo/gibbs', q: 'CaCO₃ → CaO + CO₂: ΔH° = +178 kJ, ΔS° = +160 J/K. Decomposition becomes spontaneous above…', opts: ['298.0 K', 'about 500 K', 'never at any T', '~1110 K, where ΔG turns'], a: 3, why: 'T = ΔH/ΔS = 178000/160 ≈ 1113 K (~840 °C) — why limestone kilns run hot.', misconception: 'With ΔH and ΔS both positive there is always a crossover temperature, so "never spontaneous" is a sign-reading error — the reaction is simply non-spontaneous while TΔS is smaller than ΔH. The other trap is units: ΔH is in kJ and ΔS in J/K, and 178/160 gives a nonsensical 1.1 K where 178 000/160 gives the real 1113 K.' },
  { id: 'th2-013', topic: 'thermo2', skill: 'thermo/entropy', q: 'An exothermic reaction increases the entropy of the SURROUNDINGS because…', opts: ['released heat disperses outward', 'it orders the product molecules', 'ΔS of the system must be positive', 'the temperature falls as it goes'], a: 0, why: 'ΔSsurr = −ΔH/T > 0 when ΔH < 0. This term is why many exothermic reactions are spontaneous even with ΔSsys < 0.', misconception: 'The second law constrains the entropy of the <em>universe</em>, not of the system. An exothermic reaction dumps heat into its surroundings, raising their entropy by ΔS_surr = −ΔH/T — and that term is often what makes ΔS_universe positive even when the system itself becomes more ordered. Judging spontaneity from ΔS_sys alone is why "exothermic reactions that lose entropy" look impossible when they are routine.' },
  { id: 'th2-014', topic: 'thermo2', skill: 'thermo/gibbs', q: 'NH₄NO₃ dissolves spontaneously although the beaker gets COLD. The process is driven by…', opts: ['enthalpy', 'entropy', 'pressure', 'a catalyst'], a: 1, why: 'ΔH > 0 (endothermic — cold packs!) but the ions dispersing through water give ΔS ≫ 0, making ΔG < 0.', misconception: 'Endothermic does not mean non-spontaneous. NH₄NO₃ dissolving takes heat from the beaker (that is what makes an instant cold pack work), but the ions dispersing through the solvent give a large positive ΔS, and TΔS outweighs ΔH. Spontaneity is decided by ΔG, and using ΔH as a proxy for it fails for exactly this class of process.' },
  { id: 'th2-015', topic: 'thermo2', skill: 'equilibrium/le-chatelier', q: 'For an exothermic reaction, raising the temperature makes K…', opts: ['larger', 'unchanged', 'smaller', 'exactly 1'], a: 2, why: 'van \'t Hoff: ln K falls as T rises when ΔH° < 0 — heat is a "product," so adding it pushes back.' , why2: 'Put numbers on van \'t Hoff and the direction stops being a memory item. Take ΔH° = −50 kJ/mol with ΔS° = 0: K = e<sup>−ΔH°/RT</sup> gives e<sup>20.2</sup> ≈ 6×10⁸ at 298 K, but only e<sup>15.1</sup> ≈ 4×10⁶ at 398 K — a 160-fold collapse for a 100 K rise. Microscopically, heating populates higher-energy states, which always favours whichever direction is <em>endothermic</em>; for an exothermic forward reaction that is the reverse, so K falls. Note what does not change: ΔH° and ΔS° are (near enough) constant, and it is only the balance between them in ΔG° = ΔH° − TΔS° that T is rewriting.' },
  { id: 'th2-016', topic: 'thermo2', skill: 'thermo/gibbs', q: 'K = 100 at 298 K. ΔG° ≈ ?', opts: ['−2.5 kJ/mol', '+11.4 kJ/mol', '−100 kJ/mol', '−11.4 kJ/mol'], a: 3, why: 'ΔG° = −RT ln K = −8.314 × 298 × ln(100) = −11.4 kJ/mol. Each factor of 10 in K ≈ 5.7 kJ/mol at 25 °C.' },
  { id: 'th2-017', topic: 'thermo2', skill: 'thermo/gibbs', q: 'ΔG° > 0 for a reaction. This means…', opts: ['K < 1, but some product still forms', 'no product is ever formed', 'the reverse reaction is fast', 'ΔH is necessarily positive'], a: 0, why: 'ΔG° sets WHERE equilibrium sits, not whether anything happens. Some product always forms.' },
  { id: 'th2-018', topic: 'thermo2', skill: 'thermo/entropy', q: 'Sign of ΔS° for 2H₂(g) + O₂(g) → 2H₂O(g)?', opts: ['positive', 'negative', 'zero', 'cannot tell'], a: 1, why: '3 mol gas → 2 mol gas — fewer gas particles, fewer microstates, ΔS < 0. (Still spontaneous: huge −ΔH.)' },
  { id: 'th2-019', topic: 'thermo2', skill: 'thermo/entropy', q: 'Living organisms build ordered structures without violating the second law because…', opts: ['biology is exempt from it', 'their total ΔS is zero', 'they export more entropy than they lose', 'the enzymes change K'], a: 2, why: 'ΔS(universe) = ΔS(organism) + ΔS(surroundings) > 0 — metabolizing food dumps plenty of entropy into the environment.', misconception: 'Building an ordered organism does not break the second law, because an organism is not an isolated system. It exports far more entropy to its surroundings — as heat, CO₂ and waste — than it removes internally, so ΔS_universe still rises. The rule that entropy must increase applies only to isolated systems; any open system can lower its own entropy by raising something else\'s more.' },
  { id: 'th2-020', tier: 3, topic: 'thermo2', skill: 'thermo/entropy', q: 'Which has the higher S°: O₂(g) or O₃(g), per mole?', opts: ['O₂', 'equal', 'O₃', 'not comparable'], a: 2, why: 'More atoms per molecule = more vibrational and rotational modes to store energy in = more entropy. S°(O₃) = 239 J/mol·K vs S°(O₂) = 205 J/mol·K. Both are gases, so the phase rule of thumb can\'t separate them — molecular complexity does.', misconception: 'Entropy is not a ranking of stability or reactivity — O₂ being the stable allotrope says nothing about its S°. Both species are gases, so the phase rule of thumb is silent and molecular complexity decides: the triatomic has more rotational and vibrational modes to spread energy over, giving O₃ the larger standard entropy.' },
  { id: 'th2-021', topic: 'thermo2', skill: 'thermo/gibbs', q: 'ATP hydrolysis (ΔG° = −30 kJ) drives amino-acid coupling (ΔG° = +14 kJ). The combined ΔG° is…', opts: ['+44 kJ', '−16 kJ', '−44 kJ', '+16 kJ'], a: 1, why: 'Coupled reactions add their ΔG°: −30 + 14 = −16 kJ < 0 → spontaneous. Free-energy accounting is additive.' },
  { id: 'th2-022', topic: 'thermo2', skill: 'thermo/gibbs', q: 'Diamond → graphite has ΔG° < 0, yet diamonds persist because…', opts: ['the activation barrier is enormous', 'ΔG° is in fact positive here', 'diamond is pure carbon already', 'entropy forbids the change'], a: 0, why: 'Thermodynamics says "downhill", kinetics says "not in a billion years." Spontaneous ≠ fast.', misconception: 'Spontaneous means thermodynamically downhill; it says nothing whatever about speed. Diamond → graphite has ΔG° &lt; 0 at room temperature and yet takes geological time, because the activation barrier for rearranging the carbon lattice is enormous. Every question that mixes ΔG with a rate is testing this: thermodynamics decides the destination, kinetics decides whether you arrive this century.' },
  { id: 'th2-023', topic: 'thermo2', skill: 'thermo/entropy', q: 'One mole of ideal gas doubles its volume isothermally. ΔS = ?', opts: ['2R exactly', 'zero, isothermal', 'R alone', 'R ln 2, about 5.76 J/K'], a: 3, why: 'ΔS = nR ln(V₂/V₁) = R ln 2. Twice the space = 2^N times the microstates for N particles.' },
  { id: 'th2-024', topic: 'thermo2', skill: 'thermo/gibbs', q: 'If Q < K, then ΔG for the reaction as written is…', opts: ['positive', 'zero', 'negative', 'equal to ΔG°'], a: 2, why: 'ΔG = RT ln(Q/K); Q/K < 1 → ln negative → forward reaction is downhill until Q = K.' },
  { id: 'th2-025', topic: 'thermo2', skill: 'thermo/gibbs', q: 'Which pair makes spontaneity GUARANTEED at every temperature?', opts: ['ΔH > 0, ΔS > 0', 'ΔH < 0, ΔS > 0', 'ΔH < 0, ΔS < 0', 'ΔH > 0, ΔS < 0'], a: 1, why: 'Both terms of ΔG = ΔH − TΔS are then negative at any T. (The opposite corner is never spontaneous.)' },
];

export const EQUILIBRIUM_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'equ-001', topic: 'equilibrium', skill: 'equilibrium/k-meaning', q: 'At equilibrium…', opts: ['forward and reverse rates are equal', 'all reactions stop', 'concentrations of products and reactants are equal', 'K = 0'], a: 0, why: 'Dynamic equilibrium: both reactions run at matching rates so concentrations hold constant — they need NOT be equal to each other.', misconception: 'Equilibrium means equal <em>rates</em>, not equal concentrations. Forward and reverse reactions both continue at matching speeds, so the composition stops changing at whatever ratio K dictates — which is usually nowhere near 1:1. "Nothing is happening" and "there is as much product as reactant" are two different wrong pictures of the same idea.' },
  { id: 'equ-002', topic: 'equilibrium', skill: 'equilibrium/k-meaning', q: 'K ≫ 1 means that at equilibrium…', opts: ['reactants dominate', 'products dominate', 'nothing reacted', 'the reaction is fast'], a: 1, why: 'Big K = products win the tug-of-war. (Says nothing about speed!)', misconception: 'K measures how far a reaction goes, not how fast it gets there. A reaction with K = 10¹⁰ can be immeasurably slow (hydrogen and oxygen sit together indefinitely at room temperature), and a reaction with K near 1 can be over in microseconds. Nothing in an equilibrium constant contains a rate constant except their ratio, K = kf/kr.' },
  { id: 'equ-003', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'Adding a catalyst changes K by…', opts: ['increasing it', 'decreasing it', 'nothing', 'doubling it'], a: 2, why: 'Catalysts speed BOTH directions equally — same equilibrium, reached faster.', misconception: 'A catalyst does not improve <em>yield</em>, only the <em>time</em> taken to reach it. It lowers the activation barrier for the forward and reverse reactions by the same amount, so kf and kr rise in step and K = kf/kr is untouched. A catalysed reaction and an uncatalysed one arrive at exactly the same final mixture; one just gets there sooner.' },
  { id: 'equ-004', topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'Pure solids appear in the equilibrium expression as…', opts: ['their concentration', 'their mass', 'their volume', 'they are omitted'], a: 3, why: 'A pure solid\'s "concentration" (density/M) is constant — it\'s folded into K. Same for pure liquids.' },
  { id: 'equ-005', topic: 'equilibrium', skill: 'equilibrium/q-vs-k', q: 'If Q = K, the system…', opts: ['is at equilibrium', 'shifts to the left', 'shifts to the right', 'runs away entirely'], a: 0, why: 'Q measures where you ARE; K where you\'re GOING. Equal = arrived.' },
  // ---- olympiad ----
  { id: 'equ-006', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'Inert gas is added at CONSTANT VOLUME. The equilibrium…', opts: ['shifts toward fewer gas moles', 'does not shift at all', 'shifts toward more gas moles', 'shifts toward products'], a: 1, why: 'Partial pressures/concentrations of the reacting species are unchanged → Q still equals K. (At constant PRESSURE the volume expands → shifts toward more gas moles.)', misconception: 'The rule is not "raise the pressure → shift toward fewer moles". It is "<em>squeeze the volume</em> → shift toward fewer moles". Argon raises the total pressure while leaving every reacting species at exactly the concentration it had, so nothing in Q changes and nothing shifts. Always ask what happened to the <em>partial</em> pressures, never the total.' , why2: 'Write Q out and look for the argon. Q is built from the partial pressures of the reacting gases only, and each of those is p<sub>i</sub> = n<sub>i</sub>RT/V. Adding argon at fixed V changes no n<sub>i</sub> and no V, so every p<sub>i</sub> is exactly what it was, Q is untouched, and there is nothing to shift — even though the gauge on the flask now reads higher. That is the whole trick: "pressure" in Le Chatelier is shorthand for the partial pressures that actually appear in Q, never the total. It also explains the constant-<em>pressure</em> case in one line — there the vessel must expand to accommodate the argon, V rises, every p<sub>i</sub> falls, and now Q genuinely has changed.' },
  { id: 'equ-007', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'The ONLY stress that changes K itself is…', opts: ['adding more reactant', 'changing the volume', 'changing the temperature', 'adding a catalyst'], a: 2, why: 'K is a function of temperature alone. Everything else moves Q and the system chases K back.', misconception: '"The equilibrium shifted" and "K changed" are not the same statement. Adding reactant, changing the volume, or adding a catalyst all leave K exactly where it was — they displace Q, and the system moves until Q equals the unchanged K again. Only temperature rewrites K, because only temperature changes kf and kr by different factors.' },
  { id: 'equ-008', tier: 3, topic: 'equilibrium', skill: ['equilibrium/ksp', 'equilibrium/k-expression'], q: 'A₂B(s) ⇌ 2A⁺ + B²⁻ with molar solubility s = 1×10⁻³ M. Ksp = ?', opts: ['1×10⁻⁶', '1×10⁻⁹', '2×10⁻⁶', '4×10⁻⁹'], a: 3, why: 'Ksp = (2s)²(s) = 4s³ = 4×10⁻⁹. Forgetting the 2 inside the square is THE classic error.', misconception: 'A stoichiometric coefficient does double duty in a Ksp expression, and dropping either use is the classic error. For A₂B ⇌ 2A⁺ + B²⁻, the 2 multiplies the solubility <em>and</em> becomes the exponent: Ksp = (2s)²(s) = 4s³, not s³ or 2s³. Write the ICE row explicitly rather than lifting exponents straight off the equation.' },
  { id: 'equ-009', topic: 'equilibrium', skill: 'equilibrium/q-vs-k', q: 'Q < K means the reaction will…', opts: ['proceed forward', 'proceed reverse', 'stay put', 'reach Q = 0'], a: 0, why: 'Too few products relative to equilibrium → net forward until Q rises to K.' },
  { id: 'equ-010', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'An endothermic reaction is heated. K…', opts: ['decreases', 'is unchanged', 'increases', 'becomes negative'], a: 2, why: 'Heat behaves like a reactant; supplying it pushes the equilibrium constant itself up (van \'t Hoff).' },
  { id: 'equ-011', topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'For which reaction does Kp = Kc?', opts: ['N₂ + 3H₂ ⇌ 2NH₃', 'H₂ + I₂ ⇌ 2HI', 'PCl₅ ⇌ PCl₃ + Cl₂', 'CaCO₃ ⇌ CaO + CO₂'], a: 1, why: 'Kp = Kc(RT)^Δn — equal only when Δn(gas) = 0. HI synthesis: 2 gas moles → 2.' },
  { id: 'equ-012', tier: 3, topic: 'equilibrium', skill: ['equilibrium/ice-setup', 'equilibrium/k-expression'], q: 'N₂O₄ ⇌ 2NO₂, start 1.0 M N₂O₄, x reacts. The correct K expression is…', opts: ['(2x)²/(1−x)', 'x²/(1−x), no factor', '2x/(1−x), unsquared', '4x/(1−x)², inverted'], a: 0, why: 'The change row doubles for NO₂: [NO₂] = 2x, then it gets SQUARED → 4x²/(1−x). Both coefficient uses matter.', misconception: 'A stoichiometric coefficient does two separate jobs and both are needed. It scales the ICE change row, so [NO₂] = 2x rather than x, and it becomes the exponent in K. Using it once only — squaring x but forgetting to double it — produces x²/(1−x) and silently loses a factor of 4.' },
  { id: 'equ-013', tier: 3, topic: 'equilibrium', skill: 'equilibrium/k-manipulation', q: 'If K = 4 for A ⇌ B, then K for 2B ⇌ 2A is…', opts: ['1/4, reciprocal', '1/2, square root', '−4, sign flipped', '1/16, squared and inverted'], a: 3, why: 'Reverse → reciprocal (1/4); double → square it: (1/4)² = 1/16.', misconception: 'Reversing and scaling act on K in different ways and this question applies both: reversing takes the reciprocal, multiplying the equation through by n raises K to the nth power. Stopping at 1/4 handles the reversal and forgets the doubling, while 1/2 takes the square ROOT — the exponent applied upside down. Doubling an equation squares its K; it never doubles or halves it.' },
  { id: 'equ-014', topic: 'equilibrium', skill: 'equilibrium/k-expression', q: 'CaCO₃(s) ⇌ CaO(s) + CO₂(g) at equilibrium. Adding more CaCO₃(s)…', opts: ['shifts right', 'shifts left', 'does nothing', 'raises P(CO₂)'], a: 2, why: 'Solids aren\'t in the expression: K = [CO₂] regardless of how much rock sits in the flask. P(CO₂) is fixed by T alone.', misconception: 'Pure solids and pure liquids do not appear in K, so adding more of them cannot shift anything. However much CaCO₃ sits in the flask, K = P(CO₂) and the pressure of CO₂ depends only on temperature — a mountain of limestone gives the same answer as a pinch. What matters for a solid is only whether some is present at all.' },
  { id: 'equ-015', topic: 'equilibrium', skill: 'equilibrium/k-manipulation', q: 'K for a reaction that is the SUM of two steps equals…', opts: ['K₁ + K₂', 'K₁ × K₂', 'K₁ − K₂', 'K₁/K₂'], a: 1, why: 'Adding equations multiplies their K\'s (free energies add → exponentials multiply).' },
  { id: 'equ-016', topic: 'equilibrium', skill: ['equilibrium/ksp', 'equilibrium/le-chatelier'], q: 'AgCl solubility in 0.1 M NaCl compared to pure water is…', opts: ['much lower', 'exactly the same', 'somewhat higher', 'effectively zero'], a: 0, why: 'Common-ion effect: s = Ksp/[Cl⁻] = 1.8×10⁻¹⁰/0.1 = 1.8×10⁻⁹ M — about 10,000× less than in pure water.' },
  { id: 'equ-017', tier: 3, topic: 'equilibrium', skill: 'equilibrium/ksp', q: 'Equal concentrations of Cl⁻ and I⁻; AgNO₃ is dripped in slowly. Which precipitates first?', opts: ['AgCl (Ksp 1.8×10⁻¹⁰)', 'neither', 'both together', 'AgI (Ksp 8.5×10⁻¹⁷)'], a: 3, why: 'Same 1:1 stoichiometry → the smaller Ksp is exceeded first. AgI is ~10⁷× less soluble — the basis of selective precipitation.', misconception: 'A larger Ksp means MORE soluble, so it takes a higher Ag⁺ concentration before that solid appears — the smaller Ksp precipitates first, not the more familiar salt. Comparing Ksp values head-to-head is only legitimate because both salts here are 1:1; for salts of different stoichiometry (AgCl against Ag₂CrO₄) you must convert to molar solubilities before ranking them.', why2: 'Read it as a threshold concentration instead of a comparison of constants. If both halides start at 0.010 M, AgI begins to form once [Ag⁺] = 8.5×10⁻¹⁷/0.010 = 8.5×10⁻¹⁵ M, while AgCl needs 1.8×10⁻¹⁰/0.010 = 1.8×10⁻⁸ M — seven orders of magnitude later. That gap is what makes the separation quantitative: by the time enough Ag⁺ has been added to touch the chloride, the iodide remaining in solution is down at ~5×10⁻⁹ M, essentially all of it already on the bottom of the flask.' },
  { id: 'equ-018', topic: 'equilibrium', skill: 'equilibrium/approximations', q: 'The "small-x" approximation is safe when…', opts: ['K is very large', 'the temperature is low', 'x < 5% of the initial', 'the reaction happens to be exothermic'], a: 2, why: 'Rule of thumb: if 100·x/C₀ < 5%, dropping x from (C₀ − x) errs less than the data. Check AFTER solving!' },
  { id: 'equ-019', topic: 'equilibrium', skill: 'equilibrium/ksp', q: 'Mg(OH)₂ is MORE soluble in acidic solution because…', opts: ['the acid raises the value of Ksp', 'H⁺ removes OH⁻, pulling it right', 'Mg²⁺ is amphoteric in acid', 'the ionic strength falls sharply'], a: 1, why: 'H⁺ + OH⁻ → H₂O strips a product away; Le Chatelier drags more solid into solution. Any basic-anion salt (carbonates, sulfides, fluorides) does this.' },
  { id: 'equ-020', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'The Haber process runs at ~450 °C even though K is bigger at 25 °C because…', opts: ['K is in fact larger when hot', 'the rate at 25 °C is far too slow', 'the ammonia decomposes when cold', 'the iron catalyst would melt otherwise'], a: 1, why: 'Classic thermodynamics-vs-kinetics compromise: sacrifice some K for an acceptable rate, then recover yield with high pressure and NH₃ removal.' },
  { id: 'equ-021', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'At equilibrium, adding a catalyst causes…', opts: ['a shift to the right', 'a shift to the left', 'no change in composition', 'the value of K to rise'], a: 2, why: 'The system is already at Q = K; speeding both directions equally changes nothing.' },
  { id: 'equ-022', topic: 'equilibrium', skill: 'equilibrium/approximations', q: 'Diluting a weak-acid solution makes its PERCENT ionization…', opts: ['decrease', 'drop to zero', 'stay constant', 'increase'], a: 3, why: 'Ostwald dilution law: Q drops below Ka on dilution → more HA dissociates fractionally (even as pH drifts up toward 7).', misconception: 'Diluting a weak acid raises its percent ionisation while <em>lowering</em> its [H⁺] — the two move in opposite directions, which is why this feels contradictory. Ka is fixed, so as concentration falls the fraction dissociated must rise (Ostwald\'s dilution law); the absolute concentration of H⁺ still drops, and the pH still climbs toward 7. Reading "more ionised" as "more acidic" is the mistake.' },
  { id: 'equ-023', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'For N₂ + 3H₂ ⇌ 2NH₃, compressing the mixture at constant T shifts it…', opts: ['right', 'left', 'not at all', 'to pure NH₃'], a: 0, why: '4 gas moles → 2: shrinking the volume favors the side with fewer gas molecules. This is why Haber uses ~200 atm.', misconception: 'Pressure moves the <em>position</em> of an equilibrium, not the value of K. Compressing the mixture raises every partial pressure, but it raises the denominator of Q faster than the numerator, so Q ≠ K and the system responds — chasing the <em>same</em> K it always had. Only temperature edits K itself.' },
  { id: 'equ-024', topic: 'equilibrium', skill: 'equilibrium/le-chatelier', q: 'K changes from 10 to 1000 when T rises from 300 K to 400 K. The reaction is…', opts: ['exothermic overall', 'endothermic, K rising with T', 'athermal, ΔH = 0', 'thermodynamically impossible'], a: 1, why: 'K rising with temperature = heat is being consumed = ΔH° > 0 (van \'t Hoff: ln K vs 1/T slopes downward, i.e. −ΔH/R < 0).' },
  { id: 'equ-025', topic: 'equilibrium', skill: 'equilibrium/k-meaning', q: 'The equilibrium constant is dimensionless because it is properly defined with…', opts: ['mole fractions throughout', 'the masses involved', 'activities, not concentrations', 'the volumes involved'], a: 2, why: 'Each concentration is implicitly divided by the 1 M (or 1 bar) standard state — which is why we can take ln K in ΔG° = −RT ln K.' },
];
